"Der Graph ist punktsymmetrisch zum Ursprung ({0}|{1}). Eine Funktion ist ungerade, wenn {2} = −{3} gilt. Alle Terme haben ungerade Exponenten.": "Wykres jest symetryczny względem początku układu ({0}|{1}). Funkcja jest nieparzysta, gdy {2} = −{3}. Wszystkie wyrazy mają wykładniki nieparzyste.",
"Der Graph ist symmetrisch zur y-Achse. Eine Funktion ist gerade, wenn {0} = {1} gilt. Alle Terme haben gerade Exponenten.": "Wykres jest symetryczny względem osi y. Funkcja jest parzysta, gdy {0} = {1}. Wszystkie wyrazy mają parzyste wykładniki.",
"Der Graph schneidet die y-Achse dort, wo {0} ist. Also {1} berechnen:": "Wykres przecina oś y tam, gdzie {0}. Oblicz więc {1}:",
"Der Graph von {0} = x² ist eine nach oben geöffnete Parabel.": "Wykresem {0} = x² jest parabola o ramionach skierowanych do góry.",
"Der Hochpunkt oder Tiefpunkt einer Parabel. Bei {0} = ax² + bx + c berechnet man ihn über die Scheitelpunktformel. Scheitelpunktform: {1} = {2}² + yₛ.": "Maksimum lub minimum paraboli. Dla {0} = ax² + bx + c oblicza się je ze wzoru na wierzchołek. Postać kanoniczna: {1} = {2}² + yₛ.",
"Der Koeffizient ist negativ": "Współczynnik jest ujemny",
"Der Koeffizient ist negativ und der Exponent {0} ist gerade — bei {1} wechselt das Vorzeichen.": "Współczynnik jest ujemny, a wykładnik {0} jest parzysty — w {1} znak się zmienia.",
"Der Koeffizient ist negativ und der Exponent {0} ist gerade — das Vorzeichen bleibt erhalten.": "Współczynnik jest ujemny, a wykładnik {0} jest parzysty — znak się nie zmienia.",
"Der Koeffizient ist negativ und der Exponent {0} ist gerade.": "Współczynnik jest ujemny, a wykładnik {0} jest parzysty.",
"Der Koeffizient ist negativ und der Exponent {0} ist ungerade — bei {1} wechselt das Vorzeichen.": "Współczynnik jest ujemny, a wykładnik {0} jest nieparzysty — w {1} znak się zmienia.",
"Der Koeffizient ist negativ und der Exponent {0} ist ungerade — das Vorzeichen bleibt erhalten.": "Współczynnik jest ujemny, a wykładnik {0} jest nieparzysty — znak się nie zmienia.",
