"Punkt setzen: in den Plot klicken. Punkte lassen sich danach ziehen.": "Ustaw punkt: kliknij w wykresie. Punkty można potem przeciągać.",
"Punkt auf Graph: auf eine Kurve klicken. Der Punkt bleibt auf dem Graphen und lässt sich daran entlang ziehen.": "Punkt na wykresie: kliknij krzywą. Punkt pozostaje na wykresie i można go przesuwać wzdłuż niego.",
