"Differenzenquotient: Die Punkte A und B auf dem Graphen ziehen. Rücken sie zusammen, wird die Sekante zur Tangente.": "Iloraz różnicowy: przeciągaj punkty A i B po wykresie. Gdy się zbliżą, sieczna staje się styczną.",
