"Beispiel:": "Przykład:",
"Ohne Zurücklegen kann man nicht mehr Kugeln ziehen, als in der Urne liegen (k ≤ n).": "Bez zwracania nie można wylosować więcej kul, niż jest w urnie (k ≤ n).",
