"Der Punkt P liegt fest auf dem Graphen, der Punkt Q wandert. Die Sekante durch P und Q hat die Steigung ms = Δy / h.": "Punkt P leży na wykresie, punkt Q się porusza. Sieczna przez P i Q ma nachylenie ms = Δy / h.",
"Ziehe Q (oder benutze den Regler) gegen P: Die Sekante wird zur Tangente, und ms nähert sich der Ableitung f′(x₀). Ziehe P, um die Stelle zu ändern.": "Przeciągnij Q (lub użyj suwaka) w stronę P: sieczna staje się styczną, a ms zbliża się do pochodnej f′(x₀). Przeciągnij P, aby zmienić punkt.",
