"Skizziere die Ableitung selbst.": "Naszkicuj pochodną samodzielnie.",
"Die Ableitung wird Schritt für Schritt mit den Ableitungsregeln berechnet. Danach folgen Tangente und Normale im Punkt P.": "Pochodna jest obliczana krok po kroku według reguł różniczkowania. Potem następują styczna i normalna w punkcie P.",
