"<0>Schritt {1}:</0> Das Intervall wird in {2} gleich breite Streifen geteilt.": "<0>Krok {1}:</0> Przedział dzielimy na {2} pasków o jednakowej szerokości.",
"<0>Schritt {1}:</0> Auf {2} wächst {3}. Darum ist der rechte Randpunkt eines Streifens der höchste.": "<0>Krok {1}:</0> Na {2} funkcja {3} rośnie. Dlatego prawy koniec paska jest najwyższy.",
"<0>Schritt {1}:</0> {2} einsetzen, ausmultiplizieren und die Summenformeln verwenden:": "<0>Krok {1}:</0> Podstawić {2}, wymnożyć i użyć wzorów na sumy:",
"<0>Schritt {1}:</0> Grenzwert für {2}: Alle Summanden mit {3} gehen gegen {4}.": "<0>Krok {1}:</0> Granica dla {2}: wszystkie składniki z {3} dążą do {4}.",
"Kontrolle mit der Stammfunktion: {0}.": "Sprawdzenie funkcją pierwotną: {0}.",
"<0>Differentialrechnung</0><1>Differenzenquotient, Sekante und Tangente, Graphisches Ableiten, Ableitungsregeln, Kurvendiskussion</1>": "<0>Rachunek różniczkowy</0><1>Iloraz różnicowy, sieczna i styczna, graficzne różniczkowanie, reguły pochodnych, badanie funkcji</1>",
"<0>Integralrechnung</0><1>Ober- und Untersummen, Integralfunktion und Hauptsatz, Stammfunktion mit Regeln, Flächen zwischen Kurven, Rotationskörper</1>": "<0>Rachunek całkowy</0><1>Sumy górne i dolne, funkcja całkowa i podstawowe twierdzenie, funkcja pierwotna z regułami, pola między krzywymi, bryły obrotowe</1>",
"<0>Algebra</0><1>Binomische Formeln, Ausmultiplizieren, Faktorisieren, quadratische Ergänzung, Potenzen, Wurzeln, Logarithmen, Bruchterme, Gleichungen und Gleichungssysteme als Bild</1>": "<0>Algebra</0><1>Wzory skróconego mnożenia, wymnażanie, rozkład na czynniki, dopełnianie do kwadratu, potęgi, pierwiastki, logarytmy, ułamki algebraiczne, równania i układy równań jako obraz</1>",
"<0>Wahrscheinlichkeit & Statistik</0><1>Zufallsexperimente zum Mitverfolgen: Würfel, Galtonbrett, π, Ziegenproblem, Grenzwertsatz, Konfidenzintervalle</1>": "<0>Prawdopodobieństwo i statystyka</0><1>Doświadczenia losowe na żywo: kostki, deska Galtona, π, problem Monty'ego Halla, centralne twierdzenie graniczne, przedziały ufności</1>",
"<0>Finanzmathematik</0><1>Zeitstrahl und Konten, Summenzeichen, Sparplan, Kredit mit Tilgungsplan, Zeitwert, Marchzins, konformer Zins</1>": "<0>Matematyka finansowa</0><1>Oś czasu i konta, znak sumy, plan oszczędzania, kredyt z harmonogramem spłat, wartość bieżąca, odsetki za dni, stopa równoważna</1>",
"Das Intervall wird in {0} gleich breite Streifen der Breite {1} geteilt. Die <2>Untersumme</2> nimmt in jedem Streifen den kleinsten, die <3>Obersumme</3> den grössten Funktionswert als Höhe des Rechtecks.": "Przedział dzielimy na {0} pasków o jednakowej szerokości {1}. <2>Suma dolna</2> bierze w każdym pasku najmniejszą wartość funkcji jako wysokość prostokąta, <3>suma górna</3> największą.",
"Für {0} streben beide Summen gegen {1}.": "Dla {0} obie sumy dążą do {1}.",
"<0>Schritt {1}:</0> {2} einsetzen, ausmultiplizieren.": "<0>Krok {1}:</0> Podstawić {2} i wymnożyć.",
"Oben der Graph von f mit der gefärbten Fläche von a bis x, unten die Integralfunktion Fa(x) = ∫ f. Ziehe den Punkt x: Der untere Punkt zeigt, wie viel Fläche bis dahin gesammelt wurde.": "U góry: wykres f z zabarwionym polem od a do x; na dole: funkcja całkowa Fa(x) = ∫ f. Przeciągnij punkt x: dolny punkt pokazuje, ile pola zebrano do tej pory.",
"Die Steigung von Fa an der Stelle x ist {0}: Wo f positiv ist, steigt Fa (grün), wo f negativ ist, fällt Fa (orange). Das ist der Hauptsatz.": "Nachylenie Fa w punkcie x wynosi {0}: tam, gdzie f jest dodatnia, Fa rośnie (zielony), tam, gdzie f jest ujemna, Fa maleje (pomarańczowy). To jest podstawowe twierdzenie.",
"Untere Grenze und Stelle": "Dolna granica i punkt",
"Stelle x": "Punkt x",
"{0} x wandert nach rechts": "{0} x przesuwa się w prawo",
"{0} <1>Fläche von a bis x färben</1>": "{0} <1>Zabarwić pole od a do x</1>",
"{0} <1>Tangente an Fa zeigen (Steigung {2})</1>": "{0} <1>Pokaż styczną do Fa (nachylenie {2})</1>",
"Rechenweg: Integralfunktion": "Obliczenie: funkcja całkowa",
"Die <0>Integralfunktion</0> sammelt die Fläche zwischen {1} und der {2}-Achse ab der festen Stelle {3}. Oberhalb der Achse wächst sie, unterhalb nimmt sie ab.": "<0>Funkcja całkowa</0> zbiera pole między {1} a osią {2} od stałego punktu {3}. Nad osią rośnie, pod osią maleje.",
"<0>Schritt {1}:</0> Eine Stammfunktion {2} von {3} bestimmen.": "<0>Krok {1}:</0> Wyznaczyć funkcję pierwotną {2} funkcji {3}.",
"<0>Schritt {1}:</0> Hauptsatz der Differential- und Integralrechnung.": "<0>Krok {1}:</0> Podstawowe twierdzenie rachunku różniczkowego i całkowego.",
"<0>Schritt {1}:</0> Ableiten der Integralfunktion gibt die Funktion zurück:": "<0>Krok {1}:</0> Różniczkowanie funkcji całkowej daje z powrotem funkcję:",
"Die Steigung von {0} an der Stelle {1} ist {2}.": "Nachylenie {0} w punkcie {1} wynosi {2}.",
"Für diese Funktion gibt es keine Stammfunktion in einfacher Form; die Integralfunktion wird numerisch berechnet.": "Ta funkcja nie ma funkcji pierwotnej w prostej postaci; funkcja całkowa jest obliczana numerycznie.",
"Die Stammfunktion wird Schritt für Schritt mit den Integrationsregeln bestimmt. Danach folgt das bestimmte Integral zwischen a und b.": "Funkcję pierwotną wyznaczamy krok po kroku regułami całkowania. Potem następuje całka oznaczona między a i b.",
"Ziehe a und b auf der x-Achse. Die Stammfunktion ist nur bis auf eine Konstante C bestimmt: Alle Stammfunktionen sind gegeneinander verschoben.": "Przeciągnij a i b po osi x. Funkcja pierwotna jest wyznaczona tylko z dokładnością do stałej C: wszystkie funkcje pierwotne są względem siebie przesunięte.",
"{0} <1>Fläche von a bis b färben</1>": "{0} <1>Zabarwić pole od a do b</1>",
"{0} <1>Stammfunktion F einzeichnen</1>": "{0} <1>Narysować funkcję pierwotną F</1>",
"{0} <1>Schar F + C zeigen (andere Konstanten)</1>": "{0} <1>Pokaż rodzinę F + C (inne stałe)</1>",
