"Dreht man den Graphen von {0} zwischen {1} und {2} um die {3}-Achse, entsteht ein Körper aus lauter dünnen Kreisscheiben mit dem Radius {4} und der Dicke {5}. Jede Scheibe hat das Volumen {6}.": "Gdy obrócimy wykres {0} między {1} a {2} wokół osi {3}, powstaje bryła złożona z wielu cienkich krążków o promieniu {4} i grubości {5}. Każdy krążek ma objętość {6}.",
