"Parabel und Gerade, Parabel aus Punkten": "Parabola i prosta, parabola z punktów",
"Eine quadratische Funktion {0} = ax² + bx + c hat eine Parabel als Graph. Der Faktor a streckt die Normalparabel (bei a {1} {2} gespiegelt), der Scheitel S ist der höchste oder tiefste Punkt.": "Funkcja kwadratowa {0} = ax² + bx + c ma jako wykres parabolę. Współczynnik a rozciąga parabolę podstawową y = x² (dla a {1} {2} jest ona odbita), wierzchołek S jest najwyższym lub najniższym punktem.",
"Ziehe den Scheitel S, den roten Punkt (a), den Achsenabschnitt c oder die Nullstellen N. Standard-, Scheitel- und Nullstellenform beschreiben dieselbe Parabel.": "Przeciągaj wierzchołek S, czerwony punkt (a), wyraz wolny c lub miejsca zerowe N. Postać ogólna, kanoniczna i iloczynowa opisują tę samą parabolę.",
