"Wähle ein Beispiel oder ändere die Zahlen. Ziehe den Punkt auf der x-Achse, um die Werte an einer Stelle zu vergleichen.": "Wybierz przykład lub zmień liczby. Przeciągnij punkt na osi x, aby porównać wartości w wybranym punkcie.",
