"<0>Schritt {1}:</0> Gleichung {2} aufstellen und {3} ablesen.": "<0>Krok {1}:</0> Ułożyć równanie {2} i odczytać {3}.",
"<0>Schritt {1}:</0> Die Diskriminante {2} sagt, wie viele Lösungen es gibt.": "<0>Krok {1}:</0> Wyróżnik {2} mówi, ile jest rozwiązań.",
"{0}: Es gibt <1>zwei</1> Lösungen. <2>Schritt {3}:</2> Mitternachtsformel einsetzen.": "{0}: Są <1>dwa</1> rozwiązania. <2>Krok {3}:</2> Podstawić do wzoru na pierwiastki.",
"<0>Probe mit Vieta:</0> Für {1} gilt {2} und {3}.": "<0>Sprawdzenie wzorami Viète'a:</0> Dla {1} zachodzi {2} i {3}.",
"<0>Nullstellenform:</0>": "<0>Postać iloczynowa:</0>",
"Nullstellen {0} und {1}": "Miejsca zerowe {0} i {1}",
"Die drei Formen im Überblick": "Przegląd trzech postaci",
"eine Nullstelle": "jedno miejsce zerowe",
"Es fehlt der Term mit {0}: Die Parabel ist schon in <1>Scheitelform</1>, der Scheitel liegt auf der {2}-Achse.": "Brak wyrazu z {0}: parabola jest już w <1>postaci kanonicznej</1>, wierzchołek leży na osi {2}.",
"{0}: Es gibt <1>genau eine</1> Lösung (doppelte Nullstelle).": "{0}: Jest <1>dokładnie jedno</1> rozwiązanie (podwójne miejsce zerowe).",
"Eine (doppelte) Nullstelle {0}: Die Parabel berührt die {1}-Achse im Scheitel.": "Jedno (podwójne) miejsce zerowe {0}: parabola dotyka osi {1} w wierzchołku.",
"nach unten geöffnet": "otwarta ku dołowi",
"Wegen {0} ist die Parabel nach unten geöffnet: Der Scheitel ist der <1>höchste</1> Punkt (Maximum {2}).": "Ponieważ {0}, parabola jest otwarta ku dołowi: wierzchołek jest punktem <1>najwyższym</1> (maksimum {2}).",
"Aus der Normalparabel {0} entsteht die Parabel durch Strecken mit {1} und Spiegeln an der {2}-Achse, dann Verschieben um {3} in {4}-Richtung und um {5} in {6}-Richtung.": "Z paraboli {0} powstaje ta parabola przez rozciągnięcie ze współczynnikiem {1} i odbicie względem osi {2}, następnie przesunięcie o {3} w kierunku {4} i o {5} w kierunku {6}.",
"enger als die Normalparabel": "węższa niż parabola y = x²",
"<0>Schritt {1}:</0> Den Faktor {2} aus den Termen mit {3} ausklammern.": "<0>Krok {1}:</0> Wyłączyć czynnik {2} przed nawias z wyrazów z {3}.",
"keine Nullstellen": "brak miejsc zerowych",
"keine Nullstelle": "brak miejsca zerowego",
"{0}: Der Radikand ist negativ, es gibt <1>keine reelle Lösung</1>.": "{0}: Wyrażenie pod pierwiastkiem jest ujemne, <1>brak rozwiązania rzeczywistego</1>.",
"Keine Nullstelle: Die Parabel liegt ganz oberhalb der {0}-Achse.": "Brak miejsca zerowego: parabola leży całkowicie nad osią {0}.",
"weiter als die Normalparabel": "szersza niż parabola y = x²",
"Nullstellen {0} und {1}, also {2} und {3}": "Miejsca zerowe {0} i {1}, czyli {2} i {3}",
"Parameter a, xs, ys": "Parametry a, xs, ys",
"Parameter a, x₁, x₂": "Parametry a, x₁, x₂",
"Diese Parabel hat keine Nullstellen, deshalb gibt es keine Nullstellenform.": "Ta parabola nie ma miejsc zerowych, dlatego nie ma postaci iloczynowej.",
"Nullstellen −{0} und {1} einsetzen": "Podstawić miejsca zerowe −{0} i {1}",
"Für {0} ist dies keine Parabel, sondern eine Gerade.": "Dla {0} nie jest to parabola, lecz prosta.",
"Für {0} ist dies eine Gerade (siehe «Lineare Funktionen»).": "Dla {0} jest to prosta (zob. «Funkcje liniowe»).",
"Für a = {0} ist es eine Gerade.": "Dla a = {0} jest to prosta.",
"Das ist keine quadratische Funktion. Erlaubt ist ax² + bx + c.": "To nie jest funkcja kwadratowa. Dozwolone jest ax² + bx + c.",
"Mit der quadratischen Ergänzung wird aus der Standardform die Scheitelform. Das zeigt, wie die Parabel aus der Normalparabel entsteht: strecken, nach rechts oder links und nach oben oder unten schieben.": "Dopełnianie do kwadratu przekształca postać ogólną w kanoniczną. Pokazuje to, jak parabola powstaje z paraboli podstawowej: rozciągnięcie, przesunięcie w prawo lub w lewo oraz w górę lub w dół.",
"Bewege den Regler «Verschiebung» oder starte die Animation: Die Normalparabel wird Schritt für Schritt in die gewählte Parabel verwandelt.": "Przesuń suwak «Przesunięcie» lub uruchom animację: parabola podstawowa jest krok po kroku przekształcana w wybraną parabolę.",
"Parabel": "Parabola",
"Verschiebung der Normalparabel": "Przesunięcie paraboli podstawowej",
"{0} Normalparabel verschieben": "{0} Przesuń parabolę podstawową",
"Fertig": "Gotowe",
"Rechenweg: Quadratische Ergänzung": "Obliczenie: dopełnianie do kwadratu",
"Quadratische Ergänzung und Scheitelpunkt": "Dopełnianie do kwadratu i wierzchołek",
"{0}. Strecken mit a": "{0}. Rozciągnięcie ze współczynnikiem a",
"{0}. Verschieben in x-Richtung": "{0}. Przesunięcie w kierunku x",
"{0}. Verschieben in y-Richtung": "{0}. Przesunięcie w kierunku y",
"Die Nullstellen sind die Lösungen von ax² + bx + c = {0}. Die Diskriminante D = b² − {1}ac zeigt, ob es zwei, eine oder keine Lösung gibt.": "Miejsca zerowe są rozwiązaniami równania ax² + bx + c = {0}. Wyróżnik D = b² − {1}ac pokazuje, czy są dwa rozwiązania, jedno, czy żadne.",
"Ziehe die Parabel (Punkt c oder Scheitel) und beobachte D. Wähle das Lösungsverfahren: Mitternachtsformel, quadratische Ergänzung oder Satz von Vieta.": "Przeciągaj parabolę (punkt c lub wierzchołek) i obserwuj D. Wybierz metodę rozwiązania: wzór na pierwiastki, dopełnianie do kwadratu lub wzory Viète'a.",
"Lösungsverfahren": "Metoda rozwiązania",
"Rechenweg: Nullstellen": "Obliczenie: miejsca zerowe",
"Die Parabel liegt ganz oberhalb der x-Achse.": "Parabola leży całkowicie nad osią x.",
"<0>Schritt {1}:</0> Mit der quadratischen Ergänzung in die Scheitelform bringen.": "<0>Krok {1}:</0> Doprowadzić do postaci kanonicznej przez dopełnianie do kwadratu.",
"<0>Schritt {1}:</0> Gleich null setzen und nach dem Quadrat auflösen.": "<0>Krok {1}:</0> Przyrównać do zera i rozwiązać względem kwadratu.",
"Ein Quadrat kann nicht negativ sein: <0>keine reelle Lösung</0>.": "Kwadrat nie może być ujemny: <0>brak rozwiązania rzeczywistego</0>.",
"Das Quadrat ist {0}: <1>eine</1> Lösung.": "Kwadrat jest równy {0}: <1>jedno</1> rozwiązanie.",
"<0>Schritt {1}:</0> Wurzel ziehen, beide Vorzeichen beachten.": "<0>Krok {1}:</0> Obliczyć pierwiastek, uwzględniając oba znaki.",
"<0>Schritt {1}:</0> Durch {2} teilen, damit vor {3} eine {4} steht (Normalform {5}).": "<0>Krok {1}:</0> Podzielić przez {2}, aby przed {3} stało {4} (postać normalna {5}).",
"Es gibt keine reellen Zahlen mit Summe {0} und Produkt {1}: <2>keine Nullstelle</2>.": "Nie ma liczb rzeczywistych o sumie {0} i iloczynie {1}: <2>brak miejsca zerowego</2>.",
"<0>Schritt {1}:</0> Zwei gleiche Zahlen mit Summe {2} und Produkt {3} (binomische Formel).": "<0>Krok {1}:</0> Dwie równe liczby o sumie {2} i iloczynie {3} (wzór skróconego mnożenia).",
"<0>Schritt {1}:</0> Gesucht sind zwei Zahlen mit Summe {2} und Produkt {3} (Satz von Vieta).": "<0>Krok {1}:</0> Szukamy dwóch liczb o sumie {2} i iloczynie {3} (wzory Viète'a).",
"<0>Schritt {1}:</0> Daraus folgt die Zerlegung in Linearfaktoren.": "<0>Krok {1}:</0> Stąd wynika rozkład na czynniki liniowe.",
"Die Lösungen sind keine einfachen Zahlen: Das Raten mit Vieta führt hier nicht weiter. Mit der Mitternachtsformel:": "Rozwiązania nie są prostymi liczbami: zgadywanie z użyciem wzorów Viète'a nie wystarcza tutaj. Ze wzoru na pierwiastki:",
"Gerade und Parabel: Gleichsetzen gibt eine quadratische Gleichung, deren Diskriminante die Anzahl der Schnittpunkte bestimmt (Sekante, Tangente, Passante). Umgekehrt legen drei Punkte, oder Scheitel und Punkt, oder zwei Nullstellen und ein Punkt eine Parabel fest.": "Prosta i parabola: przyrównanie daje równanie kwadratowe, którego wyróżnik określa liczbę punktów przecięcia (sieczna, styczna, prosta rozłączna). I odwrotnie, trzy punkty, albo wierzchołek i punkt, albo dwa miejsca zerowe i punkt wyznaczają parabolę.",
"Ziehe die Punkte und Griffe. Mit «Gerade berühren lassen» wird die Gerade bei gleicher Steigung zur Tangente.": "Przeciągaj punkty i uchwyty. Przy «Ustaw prostą jako styczną» prosta o tym samym współczynniku kierunkowym staje się styczną.",
