"Potenzfunktionen {0} = xⁿ mit natürlichem n. Für gerades n ist der Graph achsensymmetrisch zur y-Achse, für ungerades n punktsymmetrisch zum Ursprung. Alle gehen durch ({1}|{2}) und ({3}|{4}).": "Funkcje potęgowe {0} = xⁿ z wykładnikiem naturalnym n. Dla parzystego n wykres jest symetryczny względem osi y, dla nieparzystego n symetryczny względem początku układu. Wszystkie przechodzą przez ({1}|{2}) i ({3}|{4}).",
"Wähle n und ziehe den Punkt P: Der Spiegelpunkt P′ zeigt die Symmetrie. Die grauen Kurven sind die anderen Potenzfunktionen zum Vergleich.": "Wybierz n i przeciągnij punkt P: punkt symetryczny P′ pokazuje symetrię. Szare krzywe to pozostałe funkcje potęgowe dla porównania.",
"Exponent": "Wykładnik",
