"<0>Definitions- und Wertebereich:</0> Eine ungerade Wurzel gibt es auch aus negativen Zahlen, z.B. {1}.": "<0>Dziedzina i zbiór wartości:</0> Pierwiastek nieparzystego stopnia istnieje także z liczb ujemnych, np. {1}.",
"{0} ist die Umkehrfunktion von {1}": "{0} jest funkcją odwrotną do {1}",
"<0>Rationaler Exponent</0> {1}: Zähler = potenzieren, Nenner = Wurzel ziehen, in beliebiger Reihenfolge.": "<0>Wykładnik wymierny</0> {1}: licznik = potęgowanie, mianownik = pierwiastkowanie, w dowolnej kolejności.",
"Für {0} gilt: Je grösser der Exponent, desto grösser die Potenz: {1}. Zwischen {2} und {3} ist es umgekehrt.": "Dla {0} obowiązuje: Im większy wykładnik, tym większa potęga: {1}. Między {2} a {3} jest odwrotnie.",
"Die allgemeine Form {0} = a·(x−v)ⁿ + h entsteht aus der Grundfunktion xⁿ (oder ⁿ√x, {1}/xⁿ) durch Strecken mit a (bei a {2} {3} gespiegelt), Verschieben um v nach rechts und um h nach oben.": "Postać ogólna {0} = a·(x−v)ⁿ + h powstaje z funkcji podstawowej xⁿ (lub ⁿ√x, {1}/xⁿ) przez rozciągnięcie o a (dla a {2} {3} z odbiciem), przesunięcie o v w prawo i o h w górę.",
"Ziehe den Punkt S (bzw. Z, P) und den roten Punkt a, oder starte die Animation: Die Grundfunktion wird Schritt für Schritt in f verwandelt.": "Przeciągnij punkt S (lub Z, P) i czerwony punkt a albo uruchom animację: Funkcja podstawowa jest krok po kroku przekształcana w f.",
