"Startpunkt": "Punkt początkowy",
"<0>Definitions- und Wertebereich:</0> Unter der geraden Wurzel darf nichts Negatives stehen: {1}.": "<0>Dziedzina i zbiór wartości:</0> Pod pierwiastkiem parzystego stopnia nie może stać nic ujemnego: {1}.",
