"Intervalle auf der Zahlengeraden in drei Schreibweisen: als Intervall, als Ungleichung und in Mengenschreibweise. Dazu Schnittmenge, Vereinigung, Differenz und Komplement von zwei Intervallen.": "Przedziały na osi liczbowej w trzech zapisach: jako przedział, jako nierówność i w zapisie zbiorów. Do tego część wspólna, suma, różnica i dopełnienie dwóch przedziałów.",
