"Diese Startseite öffnest du jederzeit mit «Startseite» oben links, dem Logo oder dem Themenknopf in der Leiste. «Weiter mit …» oben rechts führt zurück zum zuletzt gewählten Thema.": "Tę stronę startową otworzysz w każdej chwili przyciskiem „Strona startowa” u góry po lewej, logo albo przyciskiem tematów na pasku. „Dalej: …” u góry po prawej prowadzi z powrotem do ostatnio wybranego tematu.",
"Der Knopf «? Hilfe zum Thema» in der Leiste erklärt, was im aktuellen Thema und in der aktuellen Ansicht besonders ist.": "Przycisk „? Pomoc do tematu” na pasku wyjaśnia, co jest szczególnego w bieżącym temacie i w bieżącym widoku.",
