"Beliebige Funktionen zeichnen und untersuchen: Nullstellen, Extrema, Ableitung, Stammfunktion, Parameter mit Schiebern, Balken über den Stellen, Punkte setzen": "Rysowanie i badanie dowolnych funkcji: miejsca zerowe, ekstrema, pochodna, funkcja pierwotna, parametry z suwakami, słupki nad argumentami, wstawianie punktów",
