"Beim zweiten Strahlensatz gehören zu den Parallelen immer die Abschnitte von {0} aus, nicht die Abschnitte {1} und {2}.": "W drugiej postaci twierdzenia Talesa prostym równoległym odpowiadają zawsze odcinki mierzone od {0}, a nie odcinki {1} i {2}.",
"<0>Fehlende Länge berechnen:</0> Gesucht ist {1}, bekannt sind {2}, {3} und {4}. Verhältnisgleichung aufstellen und nach {5} auflösen:": "<0>Obliczanie brakującej długości:</0> szukamy {1}; znamy {2}, {3} i {4}. Ułóż proporcję i wyznacz {5}:",
"<0>Zweiter Strahlensatz:</0> Die Parallelen stehen im gleichen Verhältnis wie die Abschnitte von {1} aus.": "<0>Twierdzenie Talesa (proste równoległe):</0> odcinki na prostych równoległych pozostają w tym samym stosunku co odcinki mierzone od {1}.",
"Ebenso die Abschnitte zwischen den Parallelen:": "Tak samo odcinki między prostymi równoległymi:",
"<0>Erster Strahlensatz:</0> Die Abschnitte von {1} aus stehen auf beiden Strahlen im gleichen Verhältnis.": "<0>Twierdzenie Talesa (odcinki):</0> odcinki mierzone od {1} pozostają na obu półprostych w tym samym stosunku.",
"<0>Ähnliche Dreiecke:</0> Weil {1}, stimmen {2} und {3} in allen Winkeln überein (gemeinsamer Winkel bei {4}, Stufenwinkel an Parallelen).": "<0>Trójkąty podobne:</0> ponieważ {1}, trójkąty {2} i {3} mają wszystkie kąty równe (wspólny kąt przy {4}, kąty odpowiadające przy prostych równoległych).",
"Zwei Strahlen haben den gemeinsamen Anfangspunkt {0}. {1} und {2} liegen auf dem einen, {3} und {4} auf dem anderen Strahl (V-Figur).": "Dwie półproste mają wspólny początek {0}. {1} i {2} leżą na jednej, {3} i {4} na drugiej półprostej (figura V).",
