"V-Figur": "Figura V",
"Werden zwei Strahlen mit Anfangspunkt Z von zwei Parallelen geschnitten, so sind die Dreiecke ZAB und ZCD ähnlich. Daraus folgen die Strahlensätze.": "Jeśli dwie półproste o początku Z przetniemy dwiema prostymi równoległymi, to trójkąty ZAB i ZCD są podobne. Wynika z tego twierdzenie Talesa.",
"Ziehe {0} und {1}: Zwei Parallelen schneiden die Strahlen aus Z, die Dreiecke ZAB und ZCD sind ähnlich – daraus folgen die Strahlensätze. Mit «D frei» siehst du, dass es ohne Parallelen nicht mehr stimmt.": "Przeciągaj {0} i {1}: dwie proste równoległe przecinają półproste wychodzące z Z, trójkąty ZAB i ZCD są podobne – wynika z tego twierdzenie Talesa. Po wybraniu „D swobodne” zobaczysz, że bez prostych równoległych to już nie zachodzi.",
"Vorgehen: gleiche Winkel markieren, ähnliche Dreiecke mit entsprechenden Ecken in derselben Reihenfolge notieren, Verhältnisgleichung aufstellen und lösen.": "Postępowanie: zaznacz równe kąty, zapisz trójkąty podobne z odpowiadającymi sobie wierzchołkami w tej samej kolejności, ułóż proporcję i ją rozwiąż.",
"Kontrolle mit Pythagoras:": "Sprawdzenie twierdzeniem Pitagorasa:",
"<0>Kathetensatz</0> aus {1} bzw. {2}:": "<0>Twierdzenie o przyprostokątnej</0> z {1} lub z {2}:",
"<0>Höhensatz</0> aus {1}:": "<0>Twierdzenie o wysokości</0> z {1}:",
"Entsprechende Ecken in derselben Reihenfolge: {0} (Winkel {1}), {2} (rechter Winkel), {3} (Winkel {4}).": "Odpowiadające sobie wierzchołki w tej samej kolejności: {0} (kąt {1}), {2} (kąt prosty), {3} (kąt {4}).",
"<0>Drei Dreiecke in einem:</0> Die Höhe {1} teilt das rechtwinklige Dreieck {2} in zwei Teildreiecke. Alle drei haben die Winkel {3}, {4} und {5}, also gilt": "<0>Trzy trójkąty w jednym:</0> wysokość {1} dzieli trójkąt prostokątny {2} na dwa mniejsze trójkąty. Wszystkie trzy mają kąty {3}, {4} i {5}, zatem",
"Kathetensatz:": "Twierdzenie o przyprostokątnej:",
"Höhensatz:": "Twierdzenie o wysokości:",
"gegenüber": "naprzeciw",
"Höhenfusspunkt D": "Spodek wysokości D",
"Schräg liegend": "Położony ukośnie",
"|AD| = {0}, |DB| = {1}": "|AD| = {0}, |DB| = {1}",
"Gleichschenklig (|AD| = |DB|)": "Równoramienny (|AD| = |DB|)",
"|AD| = {0}, |DB| = {1} (wie im Dossier {2} : {3})": "|AD| = {0}, |DB| = {1} (jak w materiałach {2} : {3})",
"Die Höhe CD teilt das rechtwinklige Dreieck ABC in zwei Teildreiecke. Alle drei Dreiecke haben die Winkel α, β und {0}° und sind deshalb ähnlich: ΔADC ∼ ΔCDB ∼ ΔACB.": "Wysokość CD dzieli trójkąt prostokątny ABC na dwa mniejsze trójkąty. Wszystkie trzy trójkąty mają kąty α, β i {0}°, są więc podobne: ΔADC ∼ ΔCDB ∼ ΔACB.",
"Ziehe {0} auf dem Thaleskreis oder die Ecken {1} und {2}: Die Höhe CD teilt das rechtwinklige Dreieck in zwei Teildreiecke, alle drei sind ähnlich (Winkel α, β, {3}°). Rechts stehen sie in gleicher Lage nebeneinander.": "Przeciągaj {0} po okręgu Talesa albo wierzchołki {1} i {2}: wysokość CD dzieli trójkąt prostokątny na dwa mniejsze trójkąty, a wszystkie trzy są podobne (kąty α, β, {3}°). Po prawej stoją obok siebie w tym samym położeniu.",
"Winkel und Seitenlängen lassen sich links einblenden; rechts stehen die Seitenverhältnisse als Brüche.": "Kąty i długości boków można włączyć po lewej; po prawej podane są stosunki boków w postaci ułamków.",
"«Abbildung vorführen …» spielt einzelne Abbildungen ab; «⟲ Bild auf das Original legen» stellt den Anfang wieder her.": "„Pokaż przekształcenie …” odtwarza pojedyncze przekształcenia; „⟲ Połóż obraz na oryginale” przywraca stan początkowy.",
"«Mehrere nacheinander» verknüpft die Abbildungen in fester Reihenfolge: spiegeln, um O drehen, von Z aus strecken, verschieben.": "„Kilka po kolei” składa przekształcenia w stałej kolejności: symetria, obrót wokół O, jednokładność o środku Z, przesunięcie.",
"Das Original ABC bleibt fest. Unter «Abbildung» wählst du genau eine Grundabbildung: Verschiebung, Drehung um den Ursprung, Spiegelung an der x- oder y-Achse oder zentrische Streckung von Z aus. Das Bild A′B′C′ zeigt dann nur diese eine Abbildung; du kannst es auch mit der Maus verschieben, drehen bzw. strecken.": "Oryginał ABC pozostaje nieruchomy. W polu „Przekształcenie” wybierasz dokładnie jedno przekształcenie podstawowe: przesunięcie, obrót wokół początku układu, symetrię względem osi x lub y albo jednokładność o środku Z. Obraz A′B′C′ pokazuje wtedy tylko to jedno przekształcenie; możesz go też przesuwać, obracać lub powiększać myszą.",
"Rechenweg:": "Tok rozwiązania:",
"⟲ Zurücksetzen": "⟲ Przywróć",
"Alles in dieser Ansicht in den Anfangszustand zurücksetzen (Rückgängig ist möglich)": "Przywróć wszystko w tym widoku do stanu początkowego (można cofnąć)",
