"Für {0} liegt das Bild auf der anderen Seite von {1}; es gilt {2}. Der Fall {3} ist die Punktspiegelung.": "Dla {0} obraz leży po drugiej stronie {1}; zachodzi {2}. Przypadek {3} to symetria środkowa.",
"<0>Zusammenhang:</0> Punkt und Bildpunkt liegen auf einer Geraden durch {1}, und es gilt {2} (für {3} auf der anderen Seite von {4}). Entsprechende Seiten sind parallel.": "<0>Zależność:</0> punkt i jego obraz leżą na jednej prostej przechodzącej przez {1} i zachodzi {2} (dla {3} po drugiej stronie {4}). Odpowiadające sobie boki są równoległe.",
"<0>Abbildung:</0> Punktspiegelung an {1} ({2}).": "<0>Przekształcenie:</0> symetria środkowa względem {1} ({2}).",
"Punktspiegelung an": "Symetria środkowa względem",
"<0>Abbildung:</0> Das Dreieck {1} wird nacheinander abgebildet durch: Spiegelung an der {2}-Achse, dann Verschiebung um {3} nach rechts und {4} nach unten.": "<0>Przekształcenie:</0> trójkąt {1} jest przekształcany kolejno przez: symetrię względem osi {2}, potem przesunięcie o {3} w prawo i {4} w dół.",
"Reihenfolge: zuerst spiegeln, dann um O drehen, dann von Z aus strecken, zuletzt verschieben. Jetzt: Spiegelung, dann Verschiebung.": "Kolejność: najpierw symetria, potem obrót wokół O, następnie jednokładność o środku Z, na końcu przesunięcie. Teraz: symetria, potem przesunięcie.",
"<0>Abbildung:</0> Das Dreieck {1} wird nacheinander abgebildet durch: Drehung um den Ursprung {2} um {3}, dann zentrische Streckung von {4} aus mit {5}.": "<0>Przekształcenie:</0> trójkąt {1} jest przekształcany kolejno przez: obrót wokół początku układu {2} o {3}, potem jednokładność o środku {4} i {5}.",
"nicht spiegeln": "bez symetrii",
