"Spiegelung": "Symetria",
"Reihenfolge: zuerst spiegeln, dann um O drehen, dann von Z aus strecken, zuletzt verschieben. Jetzt: Drehung, dann zentrische Streckung.": "Kolejność: najpierw symetria, potem obrót wokół O, następnie jednokładność o środku Z, na końcu przesunięcie. Teraz: obrót, potem jednokładność.",
"<0>Abbildung:</0> keine (das Bild liegt auf dem Original).": "<0>Przekształcenie:</0> brak (obraz leży na oryginale).",
"Bild = Original": "Obraz = oryginał",
"Reihenfolge: zuerst spiegeln, dann um O drehen, dann von Z aus strecken, zuletzt verschieben. Jetzt: zentrische Streckung.": "Kolejność: najpierw symetria, potem obrót wokół O, następnie jednokładność o środku Z, na końcu przesunięcie. Teraz: jednokładność.",
