"Darum geht es hier": "O co tu chodzi",
"Zwischen f und der x-Achse liegen von a bis b n gleich breite Rechtecke. Die Untersumme (grün) nimmt den kleinsten, die Obersumme (blau) den grössten Funktionswert jedes Streifens.": "Między f a osią x leży od a do b n prostokątów o równej szerokości. Suma dolna (zielona) bierze najmniejszą, a suma górna (niebieska) największą wartość funkcji w każdym pasku.",
"Eine lineare Funktion {0} = m·x + q hat als Graph eine Gerade. Die Steigung m sagt, um wie viel y pro Schritt {1} nach rechts wächst, q ist der y-Achsenabschnitt.": "Wykresem funkcji liniowej {0} = m·x + q jest prosta. Współczynnik kierunkowy m mówi, o ile rośnie y przy każdym kroku o {1} w prawo, q to wyraz wolny.",
