"rekursiv: a₁ = {0}, aₙ₊₁ = aₙ/{1} + {2}": "rekurencyjnie: a₁ = {0}, aₙ₊₁ = aₙ/{1} + {2}",
"rekursiv: a₁ = {0}, aₙ₊₁ = {1}·aₙ (Papier falten)": "rekurencyjnie: a₁ = {0}, aₙ₊₁ = {1}·aₙ (składanie papieru)",
