"Die Zielfunktion Z = px + qy soll maximal oder minimal werden. Punkte mit gleichem Z liegen auf einer Niveaulinie. Das Optimum liegt in einem Eckpunkt (oder auf einer ganzen Kante).": "Funkcja celu Z = px + qy ma być największa lub najmniejsza. Punkty o tym samym Z leżą na prostej poziomicowej. Optimum leży w wierzchołku (albo na całej krawędzi).",
