"Blickrichtung": "Kierunek patrzenia",
"Eine Ebene im Raum hat die Koordinatenform a·x + b·y + c·z = d. Der Normalenvektor (a | b | c) steht senkrecht auf ihr. Achsenabschnitte: zwei Koordinaten null setzen. Buchstaben in der Gleichung werden zu Schiebern.": "Płaszczyzna w przestrzeni ma postać ogólną a·x + b·y + c·z = d. Wektor normalny (a | b | c) jest do niej prostopadły. Punkty przecięcia z osiami: przyjmij dwie współrzędne równe zero. Litery w równaniu stają się suwakami.",
"nur Punktdiagramm": "tylko wykres punktowy",
"Kreisdiagramm": "Wykres kołowy",
"Säulendiagramm": "Wykres słupkowy",
"Histogramm": "Histogram",
"Boxplot": "Wykres pudełkowy",
"Diagramm": "Wykres",
"Einheit": "Jednostka",
"Daten": "Dane",
