"Gegeben: {0} % pro Teilperiode, {1}-mal pro Jahr": "Dane: {0} % na podokres, {1} razy w roku",
"Gegeben: {0} % pro Quartal, {1}-mal pro Jahr": "Dane: {0} % na kwartał, {1} razy w roku",
"Beim Ziegenproblem spielst du selbst: «Neues Spiel starten» und eine Tür anklicken.": "W problemie Monty'ego Halla grasz samodzielnie: „Rozpocznij nową grę” i kliknij drzwi.",
"Beobachte, wie sich die relative Häufigkeit dem theoretischen Wert nähert (gestrichelte Linie bzw. «Theoretische Wahrscheinlichkeiten zeigen»).": "Obserwuj, jak częstość względna zbliża się do wartości teoretycznej (linia przerywana lub „Pokaż prawdopodobieństwa teoretyczne”).",
"«↺ Neu beginnen» löscht die Zählung.": "„↺ Zacznij od nowa” kasuje zliczanie.",
"«+{0}», «+{1}», «+{2}» und «+{3}» führen so viele Versuche aus; «{4} Dauerlauf» lässt das Experiment laufen, der Regler stellt die Geschwindigkeit ein.": "„+{0}”, „+{1}”, „+{2}” i „+{3}” wykonują tyle prób; „{4} Praca ciągła” uruchamia doświadczenie bez przerwy, a suwak ustawia prędkość.",
"Gezinkt (eine Seite bevorzugt)": "Sfałszowana (jedna ścianka uprzywilejowana)",
"Gezinkt (höchste Seite bevorzugt)": "Sfałszowana (najwyższa ścianka uprzywilejowana)",
"Binomialverteilung einblenden": "Pokaż rozkład dwumianowy",
"Schritt t": "Krok t",
"Theorie einblenden (Hüllkurve, Normalverteilung)": "Pokaż teorię (obwiednia, rozkład normalny)",
"Normalverteilung einblenden": "Pokaż rozkład normalny",
"Mit Zurücklegen": "Ze zwracaniem",
"Das Bild zeigt die Umformung (Flächen, Plättchen, Waage), die Karte rechts den Rechenweg Schritt für Schritt.": "Rysunek pokazuje przekształcenie (pola, płytki, waga), a karta po prawej tok rozwiązania krok po kroku.",
"Mit ‹ und › blätterst du durch die Beispiele; unter «Eigene Aufgabe eingeben» tippst du einen eigenen Term oder eine eigene Gleichung.": "Znakami ‹ i › przechodzisz między przykładami; w polu „Wpisz własne zadanie” wpisujesz własne wyrażenie lub równanie.",
"Darunter drei Reiter: «Beispiele» (fertige Aufgaben zum Anklicken), «Gesetze» (die Regeln dazu) und «Üben» (Aufgaben zum Selberlösen).": "Poniżej są trzy zakładki: „Przykłady” (gotowe zadania do kliknięcia), „Prawa” (odpowiednie reguły) i „Ćwiczenia” (zadania do samodzielnego rozwiązania).",
"Oben im Panel wählst du die Art der Umformung (Ausmultiplizieren, Faktorisieren … Gleichungssysteme).": "U góry panelu wybierasz rodzaj przekształcenia (Wymnażanie, Rozkład na czynniki … Układy równań).",
"Eingabefeld: eigenen Term eintippen und mit Enter bestätigen. Das Panel «Tastatur» hilft bei Zeichen wie ², √ und π.": "Pole wpisywania: wpisz własne wyrażenie i zatwierdź klawiszem Enter. Panel „Klawiatura” pomaga przy znakach takich jak ², √ i π.",
"Mit Kacheln (Algebra-Plättchen)": "Z płytkami (płytki algebraiczne)",
"Eine Zahlung ist gesucht (Gleichung)": "Szukana jest jedna płatność (równanie)",
