"Bei einer Stichprobe teilt man oft durch {0}: {1}.": "Dla próby często dzieli się przez {0}: {1}.",
"<0>Standardabweichung:</0> mittlere Abweichung vom Mittelwert. Man quadriert die Abweichungen, bildet den Mittelwert (Varianz) und zieht die Wurzel.": "<0>Odchylenie standardowe:</0> średnie odchylenie od średniej. Odchylenia podnosi się do kwadratu, oblicza ich średnią (wariancję) i wyciąga pierwiastek.",
"Für die Quartile gibt es mehrere übliche Regeln; Taschenrechner und Programme können leicht abweichen.": "Dla kwartyli istnieje kilka przyjętych reguł; kalkulatory i programy mogą dawać nieco inne wyniki.",
"<0>Quartile:</0> Der Median teilt die Liste in eine untere und eine obere Hälfte. {1} ist der Median der unteren, {2} der Median der oberen Hälfte.": "<0>Kwartyle:</0> mediana dzieli listę na dolną i górną połowę. {1} to mediana dolnej połowy, {2} – mediana górnej połowy.",
"<0>Modus</0> (häufigster Wert): {1} ({2}-mal). <3>Spannweite:</3> {4}.": "<0>Dominanta</0> (wartość najczęstsza): {1} ({2} razy). <3>Rozstęp:</3> {4}.",
"<0>Median</0> (Zentralwert): Bei gerader Anzahl ist es der Mittelwert der beiden mittleren Werte, hier des {1}. und {2}. Werts.": "<0>Mediana</0> (wartość środkowa): przy parzystej liczbie danych jest to średnia dwóch środkowych wartości, tutaj wartości nr {1} i {2}.",
"<0>Mittelwert</0> (arithmetisches Mittel): alle Werte addieren und durch die Anzahl teilen.": "<0>Średnia</0> (średnia arytmetyczna): dodaj wszystkie wartości i podziel przez ich liczbę.",
"<0>Geordnete Liste</0> ({1} Werte):": "<0>Lista uporządkowana</0> ({1} wartości):",
