"Ziehe die {0} oder tippe links eine Liste ein: {1} und {2} wandern mit, der {3} zeigt die {4}. Wie stark zieht ein Ausreisser den Mittelwert, wie wenig den Median?": "Przeciągaj {0} albo wpisz listę po lewej: {1} i {2} przesuwają się razem z nimi, a {3} pokazuje {4}. Jak mocno wartość odstająca przesuwa średnią, a jak słabo medianę?",
"{0} Ziehe die Punkte im Bild oder ändere links die Zahlen; oben links wählst du die Ansicht, rechts steht der Rechenweg.": "{0} Przeciągaj punkty na rysunku albo zmieniaj liczby po lewej; u góry po lewej wybierasz widok, po prawej jest tok rozwiązania.",
"<0>Quartile:</0> Der Median teilt die Liste in eine untere und eine obere Hälfte (der Median selbst gehört zu keiner Hälfte). {1} ist der Median der unteren, {2} der Median der oberen Hälfte.": "<0>Kwartyle:</0> mediana dzieli listę na dolną i górną połowę (sama mediana nie należy do żadnej połowy). {1} to mediana dolnej połowy, {2} – mediana górnej połowy.",
"<0>Median</0> (Zentralwert): Bei ungerader Anzahl ist es der mittlere Wert, hier der {1}. Wert.": "<0>Mediana</0> (wartość środkowa): przy nieparzystej liczbie danych jest to wartość środkowa, tutaj wartość nr {1}.",
"Histogramm (Klassenbreite {0})": "Histogram (szerokość klasy {0})",
