"<0>{1}. Pfadregel (Summenregel):</0> Die Wahrscheinlichkeit eines Ereignisses ist die Summe der Wahrscheinlichkeiten aller Pfade, die zum Ereignis gehören. Ereignis {2}: alle Kugeln gleichfarbig.": "<0>Reguła {1} (reguła sumy):</0> prawdopodobieństwo zdarzenia jest sumą prawdopodobieństw wszystkich ścieżek należących do zdarzenia. Zdarzenie {2}: wszystkie kule tego samego koloru.",
