"Radioaktiver Zerfall: im Mittel {0} Zerfälle pro Sekunde; höchstens {1}": "Rozpad promieniotwórczy: średnio {0} rozpadów na sekundę; co najwyżej {1}",
"Notaufnahme: im Mittel {0} Patienten pro Stunde; mindestens {1} in zwei Stunden": "Izba przyjęć: średnio {0} pacjentów na godzinę; co najmniej {1} w ciągu dwóch godzin",
"Fussball: im Mittel {0} Tore pro Spiel; {1} bis {2} Tore": "Piłka nożna: średnio {0} goli na mecz; od {1} do {2} goli",
"Druckfehler: im Mittel {0} pro Seite; höchstens {1} Fehler auf {2} Seiten": "Błędy drukarskie: średnio {0} na stronę; co najwyżej {1} błędy na {2} stronach",
"Druckfehler: im Mittel {0} pro Seite; mindestens ein Fehler auf einer Seite": "Błędy drukarskie: średnio {0} na stronę; co najmniej jeden błąd na stronie",
"Telefonzentrale: im Mittel {0} Anrufe pro Minute; genau {1} Anrufe in einer Minute": "Centrala telefoniczna: średnio {0} połączeń na minutę; dokładnie {1} połączeń w ciągu minuty",
"grünen Säulen": "zielone kolumny",
"Ziehe {0} auf der Achse oder ändere links den Mittelwert λ: Die {1} sind die gesuchte Wahrscheinlichkeit. Die Verteilung liegt um {2} mit der Breite {3}; mit dem Vergleich siehst du, wie gut die {4} mit vielen Versuchen dazu passt.": "Przeciągnij {0} na osi albo zmień po lewej średnią λ: {1} to szukane prawdopodobieństwo. Rozkład leży wokół {2} z szerokością {3}; dzięki porównaniu widzisz, jak dobrze pasuje do niego {4} przy wielu próbach.",
"λ = {0} (Mittelwert für alle Einheiten zusammen, z. B. {1} Seiten oder {2} Stunden)": "λ = {0} (średnia dla wszystkich jednostek razem, np. {1} stron albo {2} godzin)",
