"Die Glockenkurve ist symmetrisch: {0}. Linksseitig und rechtsseitig ergänzen sich zu {1}, innerhalb und ausserhalb ebenfalls. Merkzahlen beidseitig: {2} sowie {3}. Bei stetigen Grössen ist {4}, darum ist es egal, ob {5} oder {6} steht.": "Krzywa dzwonowa jest symetryczna: {0}. Część lewostronna i prawostronna dają razem {1}, podobnie wnętrze i zewnętrze. Wartości warte zapamiętania (obustronnie): {2} oraz {3}. Dla wielkości ciągłych {4}, dlatego nie ma znaczenia, czy napiszemy {5}, czy {6}.",
"<0>Zum Ablesen</0> (Anteile in Prozent; {1} = Anzahl Standardabweichungen). links: {2}, rechts: {3}, innen: {4}, aussen: der Rest.": "<0>Do odczytania</0> (udziały w procentach; {1} = liczba odchyleń standardowych). po lewej: {2}, po prawej: {3}, wewnątrz: {4}, na zewnątrz: reszta.",
