"Die <0>rechtsseitige</0> und die <1>linksseitige Ableitung</1> stimmen nicht überein. Darum hat der Differenzenquotient für {2} keinen Grenzwert.": "<0>Pochodna prawostronna</0> i <1>pochodna lewostronna</1> nie są równe. Dlatego iloraz różnicowy nie ma granicy dla {2}.",
"Für {0} ist {1}, für {2} ist {3}. Der Differenzenquotient lässt sich auf beiden Seiten kürzen, ergibt aber verschiedene Werte:": "Dla {0} jest {1}, dla {2} jest {3}. Iloraz różnicowy da się skrócić po obu stronach, ale daje różne wartości:",
"Die Grenzwerte von links und rechts sind verschieden: An dieser Stelle ist {0} nicht differenzierbar (Knick).": "Granice z lewej i z prawej strony są różne: w tym miejscu {0} nie jest różniczkowalna (załamanie).",
"Die Differenzenquotienten streben von rechts und von links gegen verschiedene Werte:": "Z prawej i z lewej strony ilorazy różnicowe dążą do różnych wartości:",
"Die Differenzenquotienten haben für {0} keinen endlichen Grenzwert.": "Ilorazy różnicowe nie mają skończonej granicy dla {0}.",
"Die Differenzenquotienten wachsen für {0} über alle Grenzen: Der Graph hat an dieser Stelle eine senkrechte Tangente.": "Dla {0} ilorazy różnicowe rosną nieograniczenie: w tym miejscu wykres ma styczną pionową.",
"Die Steigung wird beliebig gross: senkrechte Tangente, {0} ist hier nicht differenzierbar.": "Nachylenie rośnie nieograniczenie: styczna pionowa, {0} nie jest tu różniczkowalna.",
