"{0}. Verschiebung um {1} nach links und {2} nach oben.": "{0}. Przesunięcie o {1} w lewo i {2} w górę.",
"<0>Abbildung:</0> Verschiebung um {1} nach links und {2} nach oben.": "<0>Przekształcenie:</0> przesunięcie o {1} w lewo i {2} w górę.",
