"Gib oben eine Funktion ein und ziehe den {0}: Jede Stelle x wird eingesetzt, das Ergebnis {1} ergibt einen {2} im Bild. Rechts steht das Einsetzen Schritt für Schritt.": "Wpisz u góry funkcję i przeciągnij {0}: każdy argument x zostaje podstawiony, a wynik {1} daje na rysunku {2}. Po prawej jest podstawianie krok po kroku.",
"im Bild: fällt auf": "na rysunku: maleje w",
"{0}, {1}; jede Stelle {2} aus {3} hat genau einen Funktionswert": "{0}, {1}; każdy argument {2} z {3} ma dokładnie jedną wartość funkcji",
"<0>Wertebereich</0> {1}: alle Werte, die {2} auf dem ganzen Definitionsbereich annimmt. Man findet ihn über den kleinsten und grössten Wert (Tief- und Hochpunkte) und über das Verhalten an den Rändern von {3}, bei Polstellen und für {4}; ein Wert, dem sich der Graph nur annähert, gehört nicht dazu.": "<0>Zbiór wartości</0> {1}: wszystkie wartości, które {2} przyjmuje w całej dziedzinie. Znajdujemy go dzięki wartości najmniejszej i największej (minima i maksima) oraz zachowaniu na krańcach {3}, przy biegunach i dla {4}; wartość, do której wykres tylko się zbliża, do niego nie należy.",
"Hier kommt keine dieser Rechnungen mit {0} vor, also darf man jede Zahl einsetzen.": "Żadne z tych działań z {0} tu nie występuje, więc można podstawić każdą liczbę.",
"<0>Definitionsbereich</0> {1}: alle {2}, die man in die Vorschrift einsetzen darf – für die ganze Funktion, nicht nur im Bild. Verboten ist, durch {3} zu teilen, die Wurzel aus einer negativen Zahl zu ziehen und den Logarithmus einer Zahl {4} zu bilden.": "<0>Dziedzina</0> {1}: wszystkie {2}, które wolno podstawić do wzoru – dla całej funkcji, nie tylko na rysunku. Nie wolno dzielić przez {3}, wyciągać pierwiastka z liczby ujemnej ani obliczać logarytmu liczby {4}.",
"im Bild:": "na rysunku:",
"senkrechte Gerade x = t": "pionową prostą x = t",
"Ziehe die {0} über das Bild: Sie trifft den {1} nie mehr als einmal – darum ist er ein Funktionsgraph. Markiert sind Nullstellen, y-Achsenabschnitt, Hoch- und Tiefpunkte.": "Przeciągnij {0} po rysunku: {1} nigdy nie spotyka jej więcej niż raz – dlatego jest wykresem funkcji. Zaznaczone są miejsca zerowe, przecięcie z osią y, maksima i minima.",
"Ablesehilfen": "linie pomocnicze",
"Wähle eine Anwendung und ziehe den {0} auf dem Graphen: An den Achsen liest du die beiden Grössen mit Einheiten ab ({1}), rechts steht, was der Wert bedeutet.": "Wybierz zastosowanie i przeciągnij {0} po wykresie: na osiach odczytujesz obie wielkości z jednostkami ({1}), a po prawej jest wyjaśnione, co oznacza wartość.",
"<0>Gefragt:</0> Welchen Wert hat {1} für {2}, und was bedeutet er?": "<0>Pytanie:</0> jaką wartość ma {1} dla {2} i co ona oznacza?",
"Fallstrecke {0} eines Steins nach {1} Sekunden: {2} (ohne Luftwiderstand).": "Droga spadku {0} kamienia po {1} sekundach: {2} (bez oporu powietrza).",
"Bei «Anwendungen» tragen die Achsen Grössen mit Einheiten; die gestrichelten Ablesehilfen führen vom Punkt zu beiden Achsen.": "W widoku „Zastosowania” na osiach są wielkości z jednostkami; przerywane linie pomocnicze prowadzą od punktu do obu osi.",
"Punkte im Bild rasten auf runden Werten ein; mit gedrückter Shift-Taste ziehst du frei.": "Punkty na rysunku przyciągają się do okrągłych wartości; z wciśniętym klawiszem Shift przeciągasz swobodnie.",
"Die drei Ansichten bauen aufeinander auf: zuerst Werte einsetzen (Wertetabelle und Punkte), dann die Eigenschaften, zum Schluss Anwendungen mit Einheiten.": "Trzy widoki wynikają jeden z drugiego: najpierw podstawianie wartości (tabela wartości i punkty), potem własności, na końcu zastosowania z jednostkami.",
"im Bild: steigt auf": "na rysunku: rośnie w",
