"Monatskosten {0}: Grundgebühr {1} Fr. plus {2} Rp. pro Gesprächsminute, {3}.": "Miesięczny koszt {0}: opłata stała {1} Fr. plus {2} Rp. za minutę rozmowy, {3}.",
