"Zu jedem {0} gehört genau ein Funktionswert {1}; die Wertetabelle entsteht durch Einsetzen, der Graph aus den Punkten {2}": "Każdemu {0} odpowiada dokładnie jedna wartość funkcji {1}; tabela wartości powstaje przez podstawianie, a wykres z punktów {2}",
"<0>Punkte im Koordinatensystem:</0> Jede Zeile der Tabelle ist ein Punkt {1}: {2} nach rechts, {3} nach oben. Alle Punkte zusammen bilden den <4>Graphen</4> von {5}.": "<0>Punkty w układzie współrzędnych:</0> każdy wiersz tabeli to punkt {1}: {2} w prawo, {3} w górę. Wszystkie punkty razem tworzą <4>wykres</4> funkcji {5}.",
"<0>Schreibweisen:</0> {1} (Funktionsgleichung), {2}, {3} (Zuordnungspfeil). Die Zahl {4} heisst <5>Argument</5> oder Stelle, {6} <7>Funktionswert</7>.": "<0>Zapisy:</0> {1} (wzór funkcji), {2}, {3} (strzałka przyporządkowania). Liczba {4} to <5>argument</5>, a {6} to <7>wartość funkcji</7>.",
"<0>Wertetabelle:</0> Man wählt Stellen {1} (hier ab {2} im Abstand {3}) und setzt jede in die Vorschrift ein. Das Einsetzen Schritt für Schritt:": "<0>Tabela wartości:</0> wybieramy argumenty {1} (tutaj od {2} co {3}) i każdy podstawiamy do wzoru. Podstawianie krok po kroku:",
"<0>Funktion = eindeutige Zuordnung:</0> Eine Funktion {1} ordnet <2>jeder</2> Zahl {3} aus dem Definitionsbereich <4>genau eine</4> Zahl {5} zu. Die Rechenvorschrift sagt, wie aus {6} der Wert {7} entsteht.": "<0>Funkcja = przyporządkowanie jednoznaczne:</0> funkcja {1} przyporządkowuje <2>każdej</2> liczbie {3} z dziedziny <4>dokładnie jedną</4> liczbę {5}. Wzór mówi, jak z {6} powstaje wartość {7}.",
