"Eine Kurve, die von einer senkrechten Geraden zweimal getroffen wird (z.B. ein Kreis), ist <0>kein</0> Funktionsgraph.": "Krzywa, którą pionowa prosta przecina dwa razy (np. okrąg), <0>nie</0> jest wykresem funkcji.",
"<0>Senkrechte-Geraden-Test:</0> Jede senkrechte Gerade {1} trifft den Graphen einer Funktion <2>höchstens einmal</2> – zu jedem {3} gehört ja nur ein Wert. Bei {4} ist das der Punkt {5}.": "<0>Test prostej pionowej:</0> każda pionowa prosta {1} przecina wykres funkcji <2>co najwyżej raz</2> – każdemu {3} odpowiada przecież tylko jedna wartość. Dla {4} jest to punkt {5}.",
"<0>Monotonie:</0> Wo der Graph von links nach rechts steigt, heisst {1} <2>steigend</2>, wo er fällt, <3>fallend</3>. Zwischen den Abschnitten liegen Hoch- und Tiefpunkte.": "<0>Monotoniczność:</0> tam, gdzie wykres wznosi się od lewej do prawej, {1} jest <2>rosnąca</2>, a tam, gdzie opada, <3>malejąca</3>. Między tymi odcinkami leżą maksima i minima.",
