"Ziehe den {0} auf dem {1}: Sein Spiegelpunkt {2} an der {3} liegt auf dem {4}. Die Umkehrfunktion vertauscht x und y; «{5} Graph an y = x umklappen» zeigt die Spiegelung als Bewegung.": "Przeciągnij {0} po {1}: jego punkt symetryczny {2} względem {3} leży na {4}. Funkcja odwrotna zamienia x i y; „{5} Odbij wykres względem y = x” pokazuje symetrię jako ruch.",
"waagrechte Gerade y = k": "poziomą prostą y = k",
"Ziehe die {0} auf und ab und zähle ihre Schnittpunkte mit dem {1}: Ist es nie mehr als einer, ist f umkehrbar. Sonst schränkt man den Definitionsbereich ein (rote Grenze r).": "Przesuwaj {0} w górę i w dół i licz punkty, w których przecina ją {1}: jeśli nigdy nie ma więcej niż jednego, f jest odwracalna. W przeciwnym razie ogranicza się dziedzinę (czerwona granica r).",
"Wähle eine Funktion: Rechts wird y = {0} nach x aufgelöst, dann werden x und y vertauscht. Zur Probe ziehe {1} auf {2}: Der Spiegelpunkt {3} liegt auf {4}.": "Wybierz funkcję: po prawej równanie y = {0} jest rozwiązywane względem x, potem x i y zamieniają się miejscami. Dla sprawdzenia przeciągnij {1} po {2}: punkt symetryczny {3} leży na {4}.",
"Wähle ein Paar und ziehe den {0} auf {1}: Sein Spiegelpunkt {2} liegt auf {3} – erst f, dann f⁻¹ führt zum Ausgangswert zurück. Beachte die eingeschränkten Bereiche bei x², sin, cos und tan.": "Wybierz parę i przeciągnij {0} po {1}: jego punkt symetryczny {2} leży na {3} – najpierw f, potem f⁻¹ prowadzi z powrotem do wartości wyjściowej. Zwróć uwagę na ograniczone dziedziny przy x², sin, cos i tan.",
"Die Winkelhalbierende y = x und die Umkehrfunktion f⁻¹ lassen sich links ein- und ausblenden.": "Dwusieczną y = x i funkcję odwrotną f⁻¹ można po lewej pokazać lub ukryć.",
"Bei «Umkehrbarkeit» ziehst du die waagrechte Gerade y = k und die rote Grenze r, die den Definitionsbereich einschränkt.": "W widoku „Odwracalność” przeciągasz poziomą prostą y = k i czerwoną granicę r, która ogranicza dziedzinę.",
"Die Funktion wählst du über «Beispiel wählen …» oder tippst sie ein (lineare Funktionen, Potenz-, Exponential- und Logarithmusfunktionen).": "Funkcję wybierasz przez „Wybierz przykład …” albo wpisujesz ją (funkcje liniowe, potęgowe, wykładnicze i logarytmiczne).",
"Umkehrfunktion des zugelassenen Astes zeigen": "Pokaż funkcję odwrotną dopuszczonej gałęzi",
"{0} ordnet jedem Funktionswert sein {1} zu; der Graph ist das Spiegelbild von {2} an {3}": "{0} przyporządkowuje każdej wartości funkcji jej {1}; wykres jest odbiciem {2} względem {3}",
"Schreibweise: {0} ist <1>nicht</1> {2}; die {3} bedeutet Umkehrung, nicht Kehrwert.": "Zapis: {0} to <1>nie</1> {2}; {3} oznacza odwrotność funkcji, a nie odwrotność liczby.",
"<0>Bereiche tauschen:</0> Was bei {1} herauskommt (Wertebereich), darf bei {2} hinein (Definitionsbereich), und umgekehrt.": "<0>Zamiana zbiorów:</0> to, co wychodzi z {1} (zbiór wartości), można podstawić do {2} (dziedzina), i odwrotnie.",
"<0>Graph:</0> Jeder Punkt {1} auf dem Graphen von {2} wird zum Punkt {3} auf dem Graphen von {4}. Koordinaten tauschen heisst <5>Spiegeln an der Winkelhalbierenden</5> {6}.": "<0>Wykres:</0> każdy punkt {1} wykresu {2} staje się punktem {3} wykresu {4}. Zamiana współrzędnych oznacza <5>odbicie względem dwusiecznej</5> {6}.",
"<0>Zuordnung rückwärts lesen:</0> {1} ordnet jedem {2} einen Wert {3} zu. Die <4>Umkehrfunktion</4> {5} macht das rückgängig: Sie ordnet jedem Wert {6} das ursprüngliche {7} zu. In der Wertetabelle werden dazu einfach die beiden Zeilen vertauscht.": "<0>Czytanie przyporządkowania wstecz:</0> {1} przyporządkowuje każdemu {2} wartość {3}. <4>Funkcja odwrotna</4> {5} to cofa: każdej wartości {6} przyporządkowuje pierwotne {7}. W tabeli wartości wystarczy zamienić oba wiersze.",
"Umkehrfunktion: Begriff": "Funkcja odwrotna: pojęcie",
