"{0} Ziehe den Punkt P auf f: Sein Spiegelpunkt liegt auf der Umkehrfunktion. Oben links wählst du die Ansicht, rechts steht der Rechenweg.": "{0} Przeciągaj punkt P po f: jego punkt symetryczny leży na funkcji odwrotnej. U góry po lewej wybierasz widok, po prawej jest tok rozwiązania.",
"{0} ist auf {1} umkehrbar (streng monoton wachsend)": "{0} jest odwracalna na {1} (ściśle rosnąca)",
"<0>Hier:</0> {1} ist auf dem ganzen Definitionsbereich streng monoton wachsend. Jede waagrechte Gerade trifft den Graphen höchstens einmal, also ist {2} <3>umkehrbar</3>.": "<0>Tutaj:</0> {1} jest ściśle rosnąca w całej dziedzinie. Każda pozioma prosta przecina wykres co najwyżej raz, więc {2} jest <3>odwracalna</3>.",
"<0>Kriterium:</0> Eine Funktion ist umkehrbar, wenn jeder Wert {1} <2>höchstens einmal</2> angenommen wird. Im Bild: Jede <3>waagrechte Gerade</3> {4} schneidet den Graphen höchstens einmal. Das ist sicher erfüllt, wenn {5} streng monoton ist.": "<0>Kryterium:</0> funkcja jest odwracalna, jeśli każdą wartość {1} przyjmuje <2>co najwyżej raz</2>. Na rysunku: każda <3>pozioma prosta</3> {4} przecina wykres co najwyżej raz. Tak jest na pewno, gdy {5} jest ściśle monotoniczna.",
"Rechenweg: Umkehrbarkeit": "Tok rozwiązania: Odwracalność",
