"Erkannt: Potenz-/Wurzelfunktion – streng monoton, umkehrbar.": "Rozpoznano: funkcja potęgowa/pierwiastkowa – ściśle monotoniczna, odwracalna.",
"Umkehrbar ist eine Funktion nur, wenn jeder Wert höchstens einmal vorkommt: Jede waagrechte Gerade darf den Graphen höchstens einmal schneiden. Streng monotone Funktionen erfüllen das. Sonst hilft eine Einschränkung des Definitionsbereichs.": "Funkcja jest odwracalna tylko wtedy, gdy każda wartość występuje co najwyżej raz: każda pozioma prosta może przeciąć wykres co najwyżej raz. Funkcje ściśle monotoniczne to spełniają. W przeciwnym razie pomaga ograniczenie dziedziny.",
