"Rechenweg: Umkehrfunktion berechnen": "Tok rozwiązania: Obliczanie funkcji odwrotnej",
"Die Umkehrfunktion berechnet man in drei Schritten: y = {0} nach x auflösen (Rechenschritte rückgängig machen), dann x und y vertauschen, dann Definitions- und Wertebereich tauschen.": "Funkcję odwrotną oblicza się w trzech krokach: rozwiązać y = {0} względem x (cofnąć działania), potem zamienić x i y, na końcu zamienić dziedzinę i zbiór wartości.",
