"<0>Abhilfe – Einschränkung:</0> Man lässt nur einen Ast zu, zum Beispiel {1}. Dort ist {2} streng monoton wachsend und darum umkehrbar.": "<0>Rozwiązanie – ograniczenie:</0> dopuszcza się tylko jedną gałąź, na przykład {1}. Tam {2} jest ściśle rosnąca, a więc odwracalna.",
