"Ziehe die Punkte bei x = {0} ({1}) und x = {2} ({3}): Bei jedem Schritt um {4} wird mit b multipliziert ({5}). Für b {6} {7} wächst der {8}, für {9} {10} b {11} {12} zerfällt er; vergleiche mit dem {13} – «{14} Schritt für Schritt wachsen lassen» baut beide nebeneinander auf.": "Przeciągaj punkty przy x = {0} ({1}) i x = {2} ({3}): przy każdym kroku o {4} mnoży się przez b ({5}). Dla b {6} {7} {8} rośnie, dla {9} {10} b {11} {12} maleje; porównaj ze {13} – „{14} Niech rośnie krok po kroku” buduje oba obok siebie.",
