"Ziehe den {0} auf dem {1}: Die Steigung der {2} ist überall genau gleich dem Funktionswert. Bei {3} stimmt das nicht – nur die Basis e ≈ {4} hat diese Eigenschaft. «{5} Basis von {6} bis {7} gleiten lassen» hält genau dort an.": "Przeciągnij {0} po {1}: nachylenie stycznej ({2}) jest wszędzie dokładnie równe wartości funkcji. Dla {3} tak nie jest – tę własność ma tylko podstawa e ≈ {4}. „{5} Przesuwaj podstawę od {6} do {7}” zatrzymuje się dokładnie tam.",
"Winkelhalbierenden": "dwusiecznej",
"Ziehe den {0} auf der {1}: Sein Spiegelpunkt {2} an der {3} liegt auf dem {4}. log_b(y) ist der Exponent, mit dem man b potenzieren muss, um y zu erhalten.": "Przeciągnij {0} po krzywej ({1}): jego punkt symetryczny {2} względem {3} leży na drugiej krzywej ({4}). log_b(y) to wykładnik, do którego trzeba podnieść b, żeby otrzymać y.",
