"Eine Zunahme um p % bedeutet Multiplikation mit q = {0} + p/{1}, eine Abnahme mit q = {2} − p/{3}. Bei mehreren Veränderungen nacheinander werden die Faktoren multipliziert, nicht die Prozente addiert. Den Grundwert findet man, indem man den neuen Wert durch den Faktor teilt.": "Wzrost o p % oznacza mnożenie przez q = {0} + p/{1}, spadek – przez q = {2} − p/{3}. Przy kilku zmianach po kolei mnoży się czynniki, a nie dodaje procenty. Wartość podstawową znajdujemy, dzieląc nową wartość przez czynnik.",
"Gesamtfaktor": "czynnik łączny",
"Säulen": "słupki",
"Ziehe die {0} hoch oder runter (oder gib die Prozente ein): Jede Veränderung um p % ist eine Multiplikation mit dem {1} {2} ± p/{3}. Alle Faktoren zusammen ergeben den {4}; rückwärts teilt man den Endwert durch ihn.": "Przeciągaj {0} w górę lub w dół (albo wpisz procenty): każda zmiana o p % to mnożenie przez liczbę {2} ± p/{3} ({1}). Wszystkie czynniki razem dają {4}; wstecz dzieli się przez niego wartość końcową.",
"Bei «Prozentrechnung» ziehst du die Säulen; «＋ Schritt» und «− Schritt» ändern die Anzahl Veränderungen, und du wählst vorwärts oder rückwärts.": "W widoku „Rachunek procentowy” przeciągasz słupki; „＋ Krok” i „− Krok” zmieniają liczbę zmian, a ty wybierasz kierunek: w przód albo wstecz.",
"Bei «Exponentialgleichungen» wählst du links eine Anwendung (Zinseszins, Zerfall, Abkühlung …) oder eine freie Gleichung; die Gerade y = c lässt sich ziehen.": "W widoku „Równania wykładnicze” wybierasz po lewej zastosowanie (procent składany, rozpad, stygnięcie …) albo dowolne równanie; prostą y = c można przeciągać.",
"Die Punkte bei x = {0} (Anfangswert a) und x = {1} (Faktor b) legen die Funktion fest; «Basis e» schaltet auf die natürliche Basis um.": "Punkty przy x = {0} (wartość początkowa a) i x = {1} (czynnik b) wyznaczają funkcję; „Podstawa e” przełącza na podstawę naturalną.",
