"<0>Verdoppelungszeit:</0> Nach welcher Zeit {1} ist der Wert doppelt so gross? Aus {2} folgt mit dem Logarithmus:": "<0>Czas podwojenia:</0> po jakim czasie {1} wartość jest dwa razy większa? Z {2} wynika dzięki logarytmowi:",
"<0>Vergleich:</0> Lineares Wachstum <1>addiert</1> pro Schritt immer dieselbe Zahl, exponentielles Wachstum <2>multipliziert</2> immer mit demselben Faktor. Darum überholt jede wachsende Exponentialfunktion irgendwann jede Gerade.": "<0>Porównanie:</0> wzrost liniowy w każdym kroku <1>dodaje</1> zawsze tę samą liczbę, wzrost wykładniczy <2>mnoży</2> zawsze przez ten sam czynnik. Dlatego każda rosnąca funkcja wykładnicza kiedyś wyprzedzi każdą prostą.",
"<0>Prozentsatz:</0> Aus {1} folgt {2}. Weil {3} ist, <4>wächst</4> {5} um {6} pro Schritt.": "<0>Stopa procentowa:</0> z {1} wynika {2}. Ponieważ {3}, {5} <4>rośnie</4> o {6} w każdym kroku.",
"<0>Basis als Faktor:</0> Geht {1} um {2} weiter, wird der Funktionswert mit {3} multipliziert, immer mit demselben Faktor.": "<0>Podstawa jako czynnik:</0> gdy {1} wzrasta o {2}, wartość funkcji mnoży się przez {3}, zawsze przez ten sam czynnik.",
