"Graph": "Wykres",
"{0} Ziehe die Punkte im Bild oder die orange Gerade. Oben links wählst du die Ansicht, rechts steht der Rechenweg.": "{0} Przeciągaj punkty na rysunku albo pomarańczową prostą. U góry po lewej wybierasz widok, po prawej jest tok rozwiązania.",
"{0} ist die Basis, bei der Funktionswert und Steigung überall übereinstimmen": "{0} to podstawa, przy której wartość funkcji i nachylenie wszędzie są równe",
"Jede Exponentialfunktion lässt sich mit der Basis {0} schreiben: {1}. Darum rechnet man in der Analysis fast nur mit {2} und {3}.": "Każdą funkcję wykładniczą można zapisać z podstawą {0}: {1}. Dlatego w analizie liczy się prawie wyłącznie z {2} i {3}.",
"<0>Andere Basen:</0> Bei {1} ist die Steigung im Punkt {2} nur {3}, bei {4} schon {5}. Genau bei der Basis {6} ist sie {7}. Allgemein gilt:": "<0>Inne podstawy:</0> dla {1} nachylenie w punkcie {2} wynosi tylko {3}, dla {4} już {5}. Dokładnie dla podstawy {6} wynosi ono {7}. Ogólnie:",
"<0>Tangente an der Stelle</0> {1}: Steigung {2}, Berührpunkt {3}.": "<0>Styczna w miejscu</0> {1}: nachylenie {2}, punkt styczności {3}.",
"<0>Die Besonderheit von</0> {1}: Die Steigung der Tangente ist an jeder Stelle gleich dem Funktionswert. Die Funktion ist ihre eigene Ableitung.": "<0>Szczególna własność</0> {1}: nachylenie stycznej jest w każdym miejscu równe wartości funkcji. Funkcja jest swoją własną pochodną.",
"<0>Woher kommt e?</0> Ein Kapital wächst um {1} pro Jahr. Wird der Zins in {2} Teilschritten gutgeschrieben, wächst es mit dem Faktor {3}. Je feiner die Schritte, desto näher kommt der Faktor einer festen Zahl:": "<0>Skąd się bierze e?</0> Kapitał rośnie o {1} rocznie. Jeśli odsetki dopisuje się w {2} częściach, rośnie on z czynnikiem {3}. Im drobniejsze kroki, tym bardziej czynnik zbliża się do pewnej stałej liczby:",
