"Die Zahl e ≈ {0} entsteht als Grenzwert von ({1} + {2}/n)ⁿ. Die Funktion eˣ hat eine besondere Eigenschaft: Die Steigung der Tangente ist an jeder Stelle gleich dem Funktionswert.": "Liczba e ≈ {0} powstaje jako granica ciągu ({1} + {2}/n)ⁿ. Funkcja eˣ ma szczególną własność: nachylenie stycznej jest w każdym miejscu równe wartości funkcji.",
"{0} ist die Umkehrfunktion von {1}: {2} und {3}": "{0} jest funkcją odwrotną do {1}: {2} oraz {3}",
"<0>Basiswechsel:</0> Der Taschenrechner kennt {1} (Basis {2}) und {3} (Basis {4}). Jeden Logarithmus erhält man als Quotient:": "<0>Zmiana podstawy:</0> kalkulator zna {1} (podstawa {2}) i {3} (podstawa {4}). Każdy logarytm otrzymujemy jako iloraz:",
"<0>Logarithmengesetze</0> (aus den Potenzgesetzen): Ein Produkt wird zur Summe, ein Quotient zur Differenz, eine Potenz zum Vielfachen.": "<0>Prawa logarytmów</0> (z praw działań na potęgach): iloczyn staje się sumą, iloraz różnicą, a potęga wielokrotnością.",
"<0>Besondere Werte:</0> {1} und {2}, also:": "<0>Szczególne wartości:</0> {1} oraz {2}, czyli:",
"<0>Definitions- und Wertebereich tauschen:</0> {1} nimmt nur positive Werte an ({2}), also ist {3} nur für positive Zahlen definiert. Die {4}-Achse ist senkrechte Asymptote von {5}.": "<0>Dziedzina i zbiór wartości zamieniają się:</0> {1} przyjmuje tylko wartości dodatnie ({2}), więc {3} jest określony tylko dla liczb dodatnich. Oś {4} jest asymptotą pionową funkcji {5}.",
"<0>Spiegelung:</0> Der Graph von {1} ist das Spiegelbild des Graphen von {2} an der Winkelhalbierenden {3}: Aus {4} wird {5}.": "<0>Symetria:</0> wykres {1} jest odbiciem wykresu {2} względem dwusiecznej {3}: z {4} powstaje {5}.",
"<0>Die Frage umdrehen:</0> Bei {1} fragt man: Welcher Wert gehört zu {2}? Die Umkehrung fragt: <3>Mit welchem Exponenten</3> muss ich {4} potenzieren, um {5} zu erhalten? Dieser Exponent heisst <6>Logarithmus</6> von {7} zur Basis {8}.": "<0>Odwrócić pytanie:</0> przy {1} pytamy: jaka wartość odpowiada {2}? Odwrotność pyta: <3>do jakiego wykładnika</3> trzeba podnieść {4}, żeby otrzymać {5}? Ten wykładnik nazywa się <6>logarytmem</6> liczby {7} o podstawie {8}.",
