"Im rechtwinkligen Dreieck gilt bezogen auf einen spitzen Winkel α: sin α = Gegenkathete : Hypotenuse, cos α = Ankathete : Hypotenuse, tan α = Gegenkathete : Ankathete. Mit zwei bekannten Stücken (darunter eine Seite) berechnet man alle anderen; dazu kommen Pythagoras und α + β = {0}°.": "W trójkącie prostokątnym względem kąta ostrego α zachodzi: sin α = przyprostokątna przeciwległa : przeciwprostokątna, cos α = przyprostokątna przyległa : przeciwprostokątna, tan α = przyprostokątna przeciwległa : przyprostokątna przyległa. Z dwóch znanych elementów (w tym jednego boku) oblicza się wszystkie pozostałe; do tego dochodzą twierdzenie Pitagorasa i α + β = {0}°.",
