"Im allgemeinen Dreieck gelten der Sinussatz a : sin α = b : sin β = c : sin γ und der Kosinussatz a² = b² + c² − {0}bc·cos α. Den Kosinussatz braucht man bei SSS und SWS, den Sinussatz bei WSW und SSW; bei SSW mit a {1} b kann es zwei Dreiecke geben.": "W dowolnym trójkącie zachodzą twierdzenie sinusów a : sin α = b : sin β = c : sin γ oraz twierdzenie cosinusów a² = b² + c² − {0}bc·cos α. Twierdzenie cosinusów jest potrzebne w przypadkach BBB i BKB, twierdzenie sinusów w przypadkach KBK i BBK; w przypadku BBK z a {1} b mogą istnieć dwa trójkąty.",
