"<0>Bogenmass:</0> Statt in Grad misst man den Winkel durch die <1>Länge des Bogens</1> auf dem Einheitskreis. Der ganze Kreis hat den Umfang {2}, also entspricht {3} dem Bogen {4} und {5} dem Bogen {6}.": "<0>Miara łukowa:</0> zamiast w stopniach kąt mierzy się <1>długością łuku</1> na okręgu jednostkowym. Cały okrąg ma długość {2}, więc kątowi {3} odpowiada łuk {4}, a kątowi {5} łuk {6}.",
"<0>Definition:</0> Der Kosinus ist die {1}-Koordinate von {2} (waagrechter Abstand), der Sinus die {3}-Koordinate (Höhe). Weil der Radius {4} ist, stimmt das mit Ankathete/Hypotenuse und Gegenkathete/Hypotenuse im rechtwinkligen Dreieck überein.": "<0>Definicja:</0> cosinus to współrzędna {1} punktu {2} (odległość pozioma), sinus to współrzędna {3} (wysokość). Ponieważ promień wynosi {4}, zgadza się to z ilorazami przyprostokątna przyległa/przeciwprostokątna i przyprostokątna przeciwległa/przeciwprostokątna w trójkącie prostokątnym.",
"<0>Einheitskreis:</0> Kreis mit Radius {1} um den Ursprung. Der Winkel {2} wird von der positiven {3}-Achse aus <4>gegen den Uhrzeigersinn</4> gemessen. Der Strahl trifft den Kreis im Punkt {5}.": "<0>Okrąg jednostkowy:</0> okrąg o promieniu {1} i środku w początku układu. Kąt {2} mierzy się od dodatniej półosi {3} <4>przeciwnie do ruchu wskazówek zegara</4>. Półprosta przecina okrąg w punkcie {5}.",
