"<0>Periode:</0> Nach einer halben Drehung zeigt der Strahl in die Gegenrichtung; Sinus und Kosinus wechseln beide das Vorzeichen, ihr Quotient bleibt gleich. Der Tangens hat darum schon die Periode {1} (Sinus und Kosinus: {2}).": "<0>Okres:</0> po połowie obrotu półprosta wskazuje przeciwny kierunek; sinus i cosinus zmieniają znak, a ich iloraz pozostaje taki sam. Dlatego tangens ma już okres {1} (sinus i cosinus: {2}).",
"<0>Definitionsbereich:</0> Der Tangens ist nicht definiert, wo der Kosinus {1} ist, also bei {2}, {3}, … Dort hat der Graph Polstellen.": "<0>Dziedzina:</0> tangens nie jest określony tam, gdzie cosinus wynosi {1}, czyli w {2}, {3}, … Wykres ma tam bieguny.",
"<0>Vorzeichen:</0> Sinus und Kosinus haben dasselbe Vorzeichen: {1} ({2}. Quadrant).": "<0>Znaki:</0> sinus i cosinus mają ten sam znak: {1} (ćwiartka {2}).",
"Werte bei": "Wartości dla",
"<0>Definition:</0> Der Tangens ist das Verhältnis von Sinus zu Kosinus, im rechtwinkligen Dreieck also Gegenkathete durch Ankathete. Im Einheitskreis ist {1} die <2>Steigung</2> des Strahls durch {3}: Er schneidet die senkrechte Tangente bei {4} in der Höhe {5}.": "<0>Definicja:</0> tangens to stosunek sinusa do cosinusa, czyli w trójkącie prostokątnym przyprostokątna przeciwległa przez przyprostokątną przyległą. Na okręgu jednostkowym {1} jest <2>współczynnikiem kierunkowym</2> półprostej przechodzącej przez {3}: przecina ona pionową styczną przy {4} na wysokości {5}.",
"Rechenweg: Tangens": "Tok rozwiązania: Tangens",
"Der Tangens ist das Verhältnis sin φ / cos φ – die Steigung des Strahls durch P. Am Einheitskreis liest man ihn an der senkrechten Tangente bei x = {0} ab. Wo der Kosinus {1} ist ({2}°, {3}°, …), hat der Tangens Polstellen; seine Periode ist nur π.": "Tangens to stosunek sin φ / cos φ – współczynnik kierunkowy półprostej przechodzącej przez P. Na okręgu jednostkowym odczytuje się go na pionowej stycznej przy x = {0}. Tam, gdzie cosinus wynosi {1} ({2}°, {3}°, …), tangens ma bieguny; jego okres to tylko π.",
"<0>Lage:</0> {1} liegt auf einer Koordinatenachse; eine der beiden Koordinaten ist {2}, die andere {3}.": "<0>Położenie:</0> {1} leży na osi układu współrzędnych; jedna z dwóch współrzędnych wynosi {2}, druga {3}.",
"<0>Vorzeichen:</0> {1} liegt im {2}. Quadranten (Sinus positiv, Kosinus negativ).": "<0>Znaki:</0> {1} leży w ćwiartce {2} (sinus dodatni, cosinus ujemny).",
