"<0>Im Bild:</0> Die Kurve mit den Punkten {1} läuft von {2} bis {3}. Die blaue Fläche zwischen Kurve und {4}-Achse ist {5}, die grüne Fläche zwischen Kurve und {6}-Achse ist {7}. Zusammen füllen sie das grosse Rechteck {8} ohne das kleine Rechteck {9}:": "<0>Na rysunku:</0> krzywa złożona z punktów {1} biegnie od {2} do {3}. Niebieskie pole między krzywą a osią {4} to {5}, zielone pole między krzywą a osią {6} to {7}. Razem wypełniają duży prostokąt {8} bez małego prostokąta {9}:",
