"Partielle Integration: ∫ u·v′ dx = [u·v] − ∫ u′·v dx. Im Bild läuft der Punkt ({0} | {1}) für x von a bis b. Die blaue Fläche links der Kurve ist ∫ u dv = ∫ u·v′ dx, die grüne Fläche unter der Kurve ist ∫ v du = ∫ v·u′ dx.": "Całkowanie przez części: ∫ u·v′ dx = [u·v] − ∫ u′·v dx. Na rysunku punkt ({0} | {1}) przesuwa się, gdy x biegnie od a do b. Niebieskie pole na lewo od krzywej to ∫ u dv = ∫ u·v′ dx, zielone pole pod krzywą to ∫ v du = ∫ v·u′ dx.",
