"<0>Im Bild:</0> Links ist die Fläche unter {1} in gleich breite Streifen der Breite {2} geteilt. Die Abbildung {3} in der Mitte bringt jeden Streifen nach rechts unter den Graphen von {4}. Dort ist er {5}-mal so breit, aber nur {6} hoch statt {7}. Die Fläche bleibt gleich. Mit dem Regler «Verformung» sieht man den Übergang fliessend: Jeder Streifen wird {8}-mal so breit und dafür {9}-mal so niedrig.": "<0>Na rysunku:</0> po lewej pole pod {1} jest podzielone na paski o jednakowej szerokości {2}. Odwzorowanie {3} pośrodku przenosi każdy pasek na prawo, pod wykres {4}. Tam jest on {5} razy szerszy, ale ma wysokość tylko {6} zamiast {7}. Pole pozostaje takie samo. Suwak „Deformacja” pokazuje to przejście płynnie: każdy pasek staje się {8} razy szerszy, a za to {9} razy niższy.",
