"Sekante": "Sieczna",
"Ziehe {0} langsam zu {1} (oder drücke «{2} h → {3}»): Die {4} durch P und Q dreht sich in die {5}, ihre Steigung {6} nähert sich der Ableitung f′(x₀). Mit {7} wechselst du die Stelle x₀.": "Przeciągaj {0} powoli do {1} (albo naciśnij „{2} h → {3}”): prosta przez P i Q ({4}) obraca się, aż powstanie {5}; jej współczynnik kierunkowy {6} zbliża się do pochodnej f′(x₀). Punktem {7} zmieniasz położenie x₀.",
