"Von rechts": "Z prawej strony",
"Von links": "Z lewej strony",
"An der Stelle {0} selbst ist {1} nicht definiert: Der Graph hat dort ein Loch (hebbare Definitionslücke).": "W samym punkcie {0} funkcja {1} nie jest określona: wykres ma tam dziurę (nieciągłość usuwalna).",
"Jetzt darf man einsetzen:": "Teraz można podstawić:",
"Zähler und Nenner werden {0}: <1>unbestimmter Ausdruck</1> {2}. Beide enthalten den Faktor {3}, den man kürzt:": "Licznik i mianownik są równe {0}: <1>wyrażenie nieoznaczone</1> {2}. Oba zawierają czynnik {3}, który się skraca:",
"<0>Einsetzen</0> von {1} in Zähler und Nenner:": "<0>Podstawienie</0> {1} do licznika i mianownika:",
"Grenzwert für {0}": "Granica dla {0}",
"Rechenweg: Grenzwert": "Tok rozwiązania: Granica",
"An der Stelle {0} ist {1} nicht definiert.": "W punkcie {0} funkcja {1} nie jest określona.",
"{0} Tangente wandern lassen": "{0} Niech styczna wędruje",
"Oben der Graph von f, unten der Graph der Ableitung f′. Ziehe den Punkt: Die Höhe des unteren Punktes ist die Steigung der Tangente oben. Der Ausschnitt richtet sich nach den Nullstellen, Extrem- und Wendepunkten. Ziehen im Bild verschiebt ihn, Mausrad oder zwei Finger zoomen, ein Klick setzt die Stelle; «⟲ Ausschnitt» stellt ihn wieder her.": "U góry wykres funkcji f, na dole wykres pochodnej f′. Przeciągaj punkt: wysokość dolnego punktu to współczynnik kierunkowy stycznej u góry. Wycinek dobiera się według miejsc zerowych, ekstremów i punktów przegięcia. Przeciąganie w rysunku przesuwa go, kółko myszy lub dwa palce powiększają, kliknięcie ustawia punkt; „⟲ Wycinek” przywraca go.",
"Hoch-, Tief- und Wendepunkten": "maksimach, minimach i punktach przegięcia",
"Ziehe den {0} entlang von {1} oder lass die Tangente wandern: Die Steigung der {2} oben ist die Höhe des Punktes auf {3} unten. An {4} rastet der Punkt ein, und die Animation wartet, bis du «{5} weiter» drückst.": "Przeciągaj {0} wzdłuż {1} albo pozwól stycznej wędrować: współczynnik kierunkowy prostej u góry ({2}) to wysokość punktu na {3} na dole. W {4} punkt się zatrzymuje, a animacja czeka, aż naciśniesz „{5} dalej”.",
"An dieser Stelle ist die Funktion nicht definiert oder nicht ableitbar.": "W tym punkcie funkcja nie jest określona albo nie jest różniczkowalna.",
"Normale": "Normalna",
"Gib eine Funktion ein und ziehe den {0} auf dem {1}: Rechts wird f′(x) mit den Ableitungsregeln berechnet, daraus die Steigung und die Gleichung der {2} in P (optional auch {3} und {4}).": "Wpisz funkcję i przeciągaj {0} po krzywej ({1}): po prawej f′(x) jest obliczana regułami różniczkowania, a z niej współczynnik kierunkowy i równanie prostej w punkcie P ({2}; opcjonalnie także {3} i {4}).",
"Gib eine Funktion ein oder wähle ein Beispiel: Am {0} sind {1}, {2} und {3} markiert, rechts stehen alle Ergebnisse. Der Rechenweg zeigt Schritt für Schritt, wie man sie findet.": "Wpisz funkcję albo wybierz przykład: na krzywej ({0}) zaznaczone są {1}, {2} i {3}, po prawej znajdują się wszystkie wyniki. Tok rozwiązania pokazuje krok po kroku, jak je znaleźć.",
"Für {0} ist {1} maximal: {2}.": "Dla {0} wartość {1} jest największa: {2}.",
"{0}. Art des Extremums": "{0}. Rodzaj ekstremum",
"{0}. Ableiten und null setzen": "{0}. Zróżniczkować i przyrównać do zera",
"{0}. Zielfunktion und Definitionsbereich": "{0}. Funkcja celu i dziedzina",
"Wähle {0} = Seite der ausgeschnittenen Quadrate (Höhe der Schachtel).": "Niech {0} = bok wyciętych kwadratów (wysokość pudełka).",
"{0}. Variable und Nebenbedingung": "{0}. Zmienna i warunek dodatkowy",
"<0>Gefragt:</0> grösstes Volumen": "<0>Pytanie:</0> największa objętość",
"Aus einem Karton {0} cm × {1} cm schneidet man an den Ecken gleich grosse Quadrate aus und faltet eine offene Schachtel. Wann ist ihr Volumen am grössten?": "Z kartonu {0} cm × {1} cm wycina się w rogach jednakowe kwadraty i składa otwarte pudełko. Kiedy jego objętość jest największa?",
"Rechenweg: Extremwertproblem": "Tok rozwiązania: Zadanie optymalizacyjne",
