"Variable": "Zmienna",
"Schachtel aus einem Karton": "Pudełko z kartonu",
"Situation wählen …": "Wybierz sytuację …",
"Extremwertprobleme löst man in fünf Schritten: Variable wählen, Nebenbedingung aufstellen, Zielfunktion mit nur einer Variablen und Definitionsbereich angeben, Ableitung null setzen, Art des Extremums prüfen und das Ergebnis deuten.": "Zadania optymalizacyjne rozwiązuje się w pięciu krokach: wybrać zmienną, zapisać warunek dodatkowy, podać funkcję celu jednej zmiennej i jej dziedzinę, przyrównać pochodną do zera, sprawdzić rodzaj ekstremum i zinterpretować wynik.",
"Optimum": "optimum",
"Wähle eine Situation und ziehe den {0} auf der {1} (oder ändere x): Das {2} zeigt die Figur zur Variablen {3}. Wo die {4} waagrecht wird, liegt das {5}. «{6} x durchlaufen lassen» fährt alle Möglichkeiten ab und zeichnet dabei die Zielfunktion.": "Wybierz sytuację i przeciągaj {0} po krzywej ({1}) albo zmień x: {2} pokazuje figurę dla zmiennej {3}. Tam, gdzie prosta ({4}) staje się pozioma, leży {5}. „{6} Przebiegnij x” przechodzi przez wszystkie możliwości i rysuje przy tym funkcję celu.",
"Punkt:": "Punkt:",
