"<0>Ansatz:</0> Polynom vom Grad {1} mit {2} Unbekannten:": "<0>Postać ogólna:</0> wielomian stopnia {1}, liczba niewiadomych: {2}:",
"Rechenweg: Polynom aus Bedingungen": "Tok rozwiązania: Wielomian z warunków",
