"{0} (Parabel): {1} Unbekannte": "{0} (parabola): niewiadome: {1}",
"Grad des Polynoms": "Stopień wielomianu",
"Ein Polynom vom Grad n hat n + {0} Koeffizienten. Jede Bedingung (Punkt, Steigung, Extremum f′ = {1}, Wendepunkt f″ = {2}) liefert eine lineare Gleichung; das Gleichungssystem bestimmt die Koeffizienten.": "Wielomian stopnia n ma n + {0} współczynników. Każdy warunek (punkt, nachylenie, ekstremum f′ = {1}, punkt przegięcia f″ = {2}) daje równanie liniowe; układ równań wyznacza współczynniki.",
"Bedingung entfernen": "Usuń warunek",
"Polynom": "Wielomian",
"Steigungen": "Nachylenia",
"Lege den Grad fest und gib die Bedingungen an – {0} oder {1} – und ziehe sie im Bild: Sobald es gleich viele Gleichungen wie Unbekannte sind, erscheint das {2}.": "Ustal stopień i podaj warunki – {0} lub {1} – a potem przeciągaj je na rysunku: gdy równań jest tyle, ile niewiadomych, pojawia się {2}.",
"Polynom aus Bedingungen: Mit «＋ Bedingung» gibst du Punkte, Extrem- und Wendepunkte oder Steigungen vor und ziehst sie im Bild.": "Wielomian z warunków: przyciskiem „＋ Warunek” zadajesz punkty, ekstrema i punkty przegięcia albo nachylenia i przeciągasz je na rysunku.",
"Kurvendiskussion: «Färbung von f» zeigt Steigen und Fallen oder die Krümmung; f′ und f″ lassen sich einzeichnen.": "Badanie funkcji: „Kolorowanie f” pokazuje wzrost i spadek albo wypukłość; można dorysować f′ i f″.",
"Graphisches Ableiten: Ein Klick setzt die Stelle, Ziehen verschiebt den Ausschnitt, an der gestrichelten Linie ziehst du den Punkt. Der Ausschnitt richtet sich nach der Funktion; «⟲ Ausschnitt» stellt ihn wieder her. Mit «f′ verstecken» skizzierst du die Ableitung selbst.": "Graficzne różniczkowanie: kliknięcie ustawia punkt, przeciąganie przesuwa wycinek, a punkt przeciągasz za przerywaną linię. Wycinek dopasowuje się do funkcji; „⟲ Wycinek” przywraca go. Po wybraniu „Ukryj f′” szkicujesz pochodną samodzielnie.",
"Sekante → Tangente: Q zu P ziehen oder «{0} h → {1}» drücken; «h = {2}» stellt den Abstand wieder her. Links wählst du, ob Q rechts oder links von P liegt.": "Sieczna → styczna: przeciągnij Q do P albo naciśnij „{0} h → {1}”; „h = {2}” przywraca odległość. Po lewej wybierasz, czy Q leży na prawo, czy na lewo od P.",
"Eigene Funktion ins Feld «{0} =» tippen und «Übernehmen»; die Stelle x₀ ziehst du im Bild oder änderst sie links mit {1} {2}.": "Wpisz własną funkcję w pole „{0} =” i naciśnij „Zastosuj”; położenie x₀ przeciągasz na rysunku albo zmieniasz po lewej przyciskami {1} {2}.",
"Sekante, Tangente, h-Methode": "Sieczna, styczna, metoda h",
"Für diese Funktion wird der Grenzwert mit einer Zahlenreihe von links und von rechts geschätzt.": "Dla tej funkcji granicę szacuje się za pomocą ciągu wartości z lewej i z prawej strony.",
"Links- und rechtsseitiger Grenzwert sind unendlich: Polstelle, der Grenzwert existiert nicht.": "Granice lewostronna i prawostronna są nieskończone: biegun, granica nie istnieje.",
"Der Nenner wird {0}, der Zähler nicht: <1>Polstelle</1>. Die Funktionswerte wachsen dem Betrag nach über alle Grenzen.": "Mianownik jest równy {0}, a licznik nie: <1>biegun</1>. Wartości funkcji rosną co do wartości bezwzględnej nieograniczenie.",
"Links- und rechtsseitiger Grenzwert stimmen nicht überein: Der Grenzwert existiert nicht.": "Granice lewostronna i prawostronna nie są równe: granica nie istnieje.",
"<0>Zahlenreihe</0> für {1}:": "<0>Ciąg wartości</0> dla {1}:",
"Waagrechte Asymptote: {0}.": "Asymptota pozioma: {0}.",
"Gleicher Grad: Es bleibt der Quotient der Leitkoeffizienten.": "Ten sam stopień: zostaje iloraz współczynników wiodących.",
"<0>Zähler und Nenner durch die höchste Potenz des Nenners teilen</0> ({1}): Alle Glieder mit {2} streben gegen {3}.": "<0>Podzielić licznik i mianownik przez najwyższą potęgę mianownika</0> ({1}): wszystkie wyrazy z {2} dążą do {3}.",
"Die Punkte liegen bei x = ±{0}/h": "Punkty leżą w x = ±{0}/h",
"Der Zähler hat den kleineren Grad: Der Bruch strebt gegen {0}.": "Licznik ma niższy stopień: ułamek dąży do {0}.",
"Für diese Funktion wird der Grenzwert mit einer Zahlenreihe geschätzt.": "Dla tej funkcji granicę szacuje się za pomocą ciągu wartości.",
"Grad Zähler = Grad Nenner + {0}: Es gibt eine schiefe Asymptote (Polynomdivision).": "Stopień licznika = stopień mianownika + {0}: istnieje asymptota ukośna (dzielenie wielomianów).",
