"Bei einer geometrischen Folge ist der Quotient q benachbarter Glieder (a₁, a₂) konstant: aₙ = a₁·qⁿ⁻¹. Für q {0} {1} exponentielles Wachstum, für {2} {3} q {4} {5} Zerfall.": "W ciągu geometrycznym iloraz q sąsiednich wyrazów (a₁, a₂) jest stały: aₙ = a₁·qⁿ⁻¹. Dla q {0} {1} wzrost wykładniczy, dla {2} {3} q {4} {5} zanik.",
