"{0} heisst: Setze für die Laufvariable {1} nacheinander alle ganzen Zahlen von der <2>unteren Grenze</2> {3} bis zur <4>oberen Grenze</4> {5} in den <6>Summanden</6> {7} ein und addiere die Ergebnisse.": "{0} oznacza: za wskaźnik {1} podstawiaj kolejno wszystkie liczby całkowite od <2>dolnej granicy</2> {3} do <4>górnej granicy</4> {5} do <6>składnika</6> {7} i dodaj wyniki.",
