"Das Summenzeichen ist eine Kurzschrift: ∑ von k = m bis n über aₖ bedeutet aₘ + aₘ₊₁ + … + aₙ. Die Laufvariable (meist k, i oder j) durchläuft alle ganzen Zahlen von der unteren bis zur oberen Grenze; es gibt n − m + {0} Summanden. Der Name der Laufvariablen spielt keine Rolle, und man kann den Index verschieben: ∑ von k = {1} bis {2} über (k − {3}) = ∑ von j = {4} bis {5} über j.": "Symbol sumy to zapis skrócony: ∑ od k = m do n z aₖ oznacza aₘ + aₘ₊₁ + … + aₙ. Wskaźnik (zwykle k, i lub j) przebiega wszystkie liczby całkowite od dolnej do górnej granicy; składników jest n − m + {0}. Nazwa wskaźnika nie ma znaczenia, a wskaźnik można przesunąć: ∑ od k = {1} do {2} z (k − {3}) = ∑ od j = {4} do {5} z j.",
"Summand (Term in k)": "Składnik (wyrażenie ze zmienną k)",
