"Lies das Summenzeichen: Die {0} sagt, bei welchem k du beginnst, die {1}, wo du aufhörst. Den {2} rechnest du für jedes k aus und addierst alle. Ziehe im Bild die Grenzen m und n und die {3}: Der Balken von k leuchtet, oben steht sein Summand. «{4} k von m bis n laufen lassen» addiert die Summanden der Reihe nach.": "Przeczytaj symbol sumy: {0} mówi, od którego k zaczynasz, {1} – na którym kończysz. Dla każdego k obliczasz {2} i wszystko dodajesz. Na rysunku przeciągaj granice m i n oraz {3}: słupek dla k się podświetla, a nad nim widać jego składnik. „{4} Niech k przebiegnie od m do n” dodaje składniki po kolei.",
"<0>Trick von Gauss:</0> Die Summe vorwärts und rückwärts untereinander schreiben. Jede Spalte ergibt {1}, und es gibt {2} Spalten: {3}.": "<0>Sztuczka Gaussa:</0> zapisać sumę od początku i od końca, jedną pod drugą. Każda kolumna daje {1}, a liczba kolumn wynosi {2}: {3}.",
"<0>Reihe</0> = Summe der ersten {1} Glieder. Mit dem Summenzeichen:": "<0>Szereg</0> = suma początkowych wyrazów (liczba wyrazów: {1}). Za pomocą symbolu sumy:",
