"Die Summe der ersten n Glieder heisst Reihe: sₙ = a₁ + … + aₙ. Arithmetisch: sₙ = n·(a₁ + aₙ)/{0} (Trick von Gauss), geometrisch: sₙ = a₁·(qⁿ − {1})/(q − {2}).": "Suma n początkowych wyrazów nazywa się szeregiem: sₙ = a₁ + … + aₙ. Arytmetyczny: sₙ = n·(a₁ + aₙ)/{0} (sztuczka Gaussa), geometryczny: sₙ = a₁·(qⁿ − {1})/(q − {2}).",
