"Ziehe den {0} im unteren Bild nach links oder rechts, um n zu ändern: Oben kommen {1} dazu oder fallen weg, unten wächst sₙ = a₁ + … + aₙ. Beim Gauss-Trick ergänzt die rückwärts gelesene Folge die Balken zu einem Rechteck («{2} Gauss-Trick als Bewegung» zeigt, wie sie sich umdreht).": "Przeciągaj {0} na dolnym rysunku w lewo lub w prawo, aby zmienić n: u góry dochodzą lub znikają {1}, na dole rośnie sₙ = a₁ + … + aₙ. W sztuczce Gaussa ciąg czytany od końca uzupełnia słupki do prostokąta („{2} Sztuczka Gaussa w ruchu” pokazuje, jak się odwraca).",
"für alle": "dla wszystkich",
"Je schmaler der Streifen, desto später beginnt er: Zu jedem {0} gibt es ein solches {1}. Wichtig: {2} und {3} für {4}.": "Im węższy pas, tym później się zaczyna: dla każdego {0} istnieje takie {1}. Ważne: {2} oraz {3} dla {4}.",
"<0>Streifen um den Grenzwert:</0> Für {1} liegen ab dem Glied {2} alle Glieder im Streifen {3}:": "<0>Pas wokół granicy:</0> dla {1} od wyrazu {2} wszystkie wyrazy leżą w pasie {3}:",
"Bei Brüchen Zähler und Nenner durch die höchste Potenz von {0} teilen; dann gehen Terme wie {1} gegen {2}.": "W ułamkach podzielić licznik i mianownik przez najwyższą potęgę {0}; wtedy wyrażenia takie jak {1} dążą do {2}.",
"<0>Konvergent:</0> Für grosse {1} kommen die Glieder der Zahl {2} beliebig nahe.": "<0>Zbieżny:</0> dla dużych {1} wyrazy zbliżają się dowolnie blisko do liczby {2}.",
"Der ε-Streifen wird laufend schmaler (die Höhe des Bildes zoomt mit), und es werden so viele Glieder gezeigt, dass man sieht: Ab N liegen wieder alle im Streifen.": "Pas ε stale się zwęża (wysokość rysunku dopasowuje się), a pokazuje się tyle wyrazów, by było widać: od N wszystkie znów leżą w pasie.",
"{0} Animation: ε → {1}": "{0} Animacja: ε → {1}",
"Streifen und Anzahl": "Pas i liczba",
"unendliche geometrische Reihe": "nieskończony szereg geometryczny",
"Grenzwert einer Folge": "Granica ciągu",
