"Reihe {0}/{1} + {2}/{3} + {4}/{5} + … (halber Weg)": "Szereg {0}/{1} + {2}/{3} + {4}/{5} + … (połowa drogi)",
"Reihe {0} + {1} + {2} + {3} + …": "Szereg {0} + {1} + {2} + {3} + …",
"aₙ = (−{0})ⁿ (divergent)": "aₙ = (−{0})ⁿ (rozbieżny)",
"aₙ = n² (divergent)": "aₙ = n² (rozbieżny)",
"aₙ = ({0} + {1}/n)ⁿ → e": "aₙ = ({0} + {1}/n)ⁿ → e",
"aₙ = (−{0})ⁿ/n": "aₙ = (−{0})ⁿ/n",
"aₙ = ({0}n² + {1})/({2}n² − n)": "aₙ = ({0}n² + {1})/({2}n² − n)",
"aₙ = ({0}n + {1})/(n + {2})": "aₙ = ({0}n + {1})/(n + {2})",
"Kommen die Glieder für grosse n einer Zahl beliebig nahe, ist das der Grenzwert. Zu jedem ε gibt es ein N, ab dem alle Glieder im ε-Streifen liegen. Eine unendliche geometrische Reihe hat für |q| {0} {1} den Wert a₁/({2} − q).": "Jeśli dla dużych n wyrazy zbliżają się dowolnie blisko do pewnej liczby, to ta liczba jest granicą. Dla każdego ε istnieje N, od którego wszystkie wyrazy leżą w pasie ε. Nieskończony szereg geometryczny ma dla |q| {0} {1} wartość a₁/({2} − q).",
"Der Streifen wird immer schmaler, und es kommen immer mehr Glieder dazu": "Pas staje się coraz węższy i dochodzi coraz więcej wyrazów",
"ε-Streifen": "pas ε",
"grünen Punkt ε": "zielony punkt ε",
"Ziehe den {0}, um den {1} um den {2} schmaler zu machen: Ab einem Index N liegen alle Glieder im Streifen – je kleiner ε, desto weiter rechts liegt N. Mit «{3} Animation: ε → {4}» wird der Streifen immer schmaler, und es kommen immer mehr Glieder dazu.": "Przeciągaj {0}, aby zwęzić {1} wokół wartości granicznej ({2}): od pewnego indeksu N wszystkie wyrazy leżą w pasie – im mniejsze ε, tym dalej w prawo leży N. Po naciśnięciu „{3} Animacja: ε → {4}” pas staje się coraz węższy i dochodzi coraz więcej wyrazów.",
"(Voraussetzung)": "(założenie)",
"{0} gilt für alle {1}.": "{0} zachodzi dla wszystkich {1}.",
"Kontrolle für {0}: linke Seite {1}, rechte Seite {2}.": "Sprawdzenie dla {0}: lewa strona {1}, prawa strona {2}.",
"<0>Bild:</0> Der erste Dominostein fällt (Anfang), und jeder Stein stösst seinen Nachfolger um (Schritt) – also fallen alle.": "<0>Obraz:</0> pierwsza kostka domina przewraca się (początek), a każda kostka przewraca następną (krok) – więc przewracają się wszystkie.",
"<0>Beweis:</0> Die ersten {1} Summanden durch die Voraussetzung ersetzen, dann umformen:": "<0>Dowód:</0> początkowe składniki (jest ich {1}) zastąpić na mocy założenia, potem przekształcić:",
"<0>{1}. Induktionsschritt.</0> Voraussetzung: {2} gilt für ein {3}. Behauptung: Dann gilt auch {4}:": "<0>{1}. Krok indukcyjny.</0> Założenie: {2} zachodzi dla pewnego {3}. Teza: wtedy zachodzi też {4}:",
"<0>{1}. Induktionsanfang</0> ({2}): beide Seiten berechnen.": "<0>{1}. Początek indukcji</0> ({2}): obliczyć obie strony.",
