"Aussage wählen …": "Wybierz stwierdzenie …",
"Vollständige Induktion: Gilt die Aussage für n = {0} (Anfang) und folgt sie für n + {1}, wenn sie für n gilt (Schritt), dann gilt sie für alle n – wie bei fallenden Dominosteinen.": "Indukcja matematyczna: jeśli stwierdzenie jest prawdziwe dla n = {0} (początek) i wynika dla n + {1}, gdy jest prawdziwe dla n (krok), to jest prawdziwe dla wszystkich n – jak przy przewracających się kostkach domina.",
"Wähle eine Aussage und lass mit «Schritt» die Dominosteine fallen: Gilt {0} und folgt aus {1} stets {2}, dann gilt die Aussage für alle n. Die letzte Aussage zeigt, warum Beispiele allein nichts beweisen.": "Wybierz stwierdzenie i przyciskiem „Krok” przewracaj kostki domina: jeśli zachodzi {0} i z {1} zawsze wynika {2}, to stwierdzenie jest prawdziwe dla wszystkich n. Ostatnie stwierdzenie pokazuje, dlaczego same przykłady niczego nie dowodzą.",
"Grenzwert: grünen Punkt ε ziehen oder «{0} Animation: ε → {1}» starten – der Streifen wird schmaler, und es kommen Glieder dazu.": "Granica: przeciągnij zielony punkt ε albo uruchom „{0} Animacja: ε → {1}” – pas się zwęża i dochodzą wyrazy.",
"Summenzeichen: Fährst du mit der Maus über die untere oder obere Grenze, leuchtet der zugehörige Summand auf.": "Symbol sumy: gdy najedziesz myszą na dolną lub górną granicę, podświetla się odpowiedni składnik.",
"Arithmetische und geometrische Folgen: a₁ und a₂ ziehen. Die rote Zielgerade t zeigt, welches Glied einen Wert erreicht.": "Ciągi arytmetyczne i geometryczne: przeciągaj a₁ i a₂. Czerwona prosta docelowa t pokazuje, który wyraz osiąga daną wartość.",
"Folge eingeben: explizit als Term in n (z. B. {0}n+{1}) oder rekursiv; die Art schaltest du links um.": "Wpisywanie ciągu: jawnie jako wyrażenie ze zmienną n (np. {0}n+{1}) albo rekurencyjnie; rodzaj przełączasz po lewej.",
"Der Quotient benachbarter Glieder ist immer {0}: Die Folge ist <1>geometrisch</1>.": "Iloraz sąsiednich wyrazów jest zawsze równy {0}: ciąg jest <1>geometryczny</1>.",
"geometrisch:": "geometryczny:",
"Für {0} braucht man rekursiv alle {1} Glieder davor; explizit genügt Einsetzen.": "Dla {0} rekurencyjnie potrzeba wszystkich poprzednich wyrazów (jest ich {1}); przy wzorze jawnym wystarczy podstawić.",
"<0>Glied für Glied</0> bis {1}:": "<0>Wyraz po wyrazie</0> aż do {1}:",
"<0>Rekursive Darstellung:</0> Man braucht den Startwert und die Regel vom Vorgänger {1} zum Nachfolger {2}.": "<0>Wzór rekurencyjny:</0> potrzebna jest wartość początkowa i reguła przejścia od poprzednika {1} do następnika {2}.",
