"<0>Gefragt:</0> Wie dick ist das Papier nach {1} Faltungen?": "<0>Pytanie:</0> Jak gruby jest papier po {1} złożeniach?",
"<0>Gefragt:</0> Wie viele Hölzer braucht man für {1} Quadrate? Für wie viele Quadrate reichen {2} Hölzer genau?": "<0>Pytanie:</0> Ile zapałek potrzeba dla {1} kwadratów? Dla ilu kwadratów wystarczy dokładnie tyle zapałek: {2}?",
"Keine natürliche Zahl: Kein Glied der Folge hat genau diesen Wert.": "To nie jest liczba naturalna: żaden wyraz ciągu nie ma dokładnie tej wartości.",
"<0>Gefragt:</0> Wie viele Bakterien sind es zu Beginn der {1}. Stunde? Ab welcher Stunde sind es mindestens {2}?": "<0>Pytanie:</0> Ile bakterii jest na początku godziny {1}? Od której godziny jest ich co najmniej {2}?",
"Eine Bakterienkultur besteht zu Beginn aus {0} Bakterien und wächst pro Stunde um {1} %. {2} = Anzahl Bakterien zu Beginn der {3}-ten Stunde.": "Kultura bakterii składa się na początku z {0} bakterii i rośnie o {1} % na godzinę. {2} = liczba bakterii na początku godziny o numerze {3}.",
"<0>Ab welchem Glied</0> gilt {1}? Ungleichung mit dem Logarithmus lösen (Achtung: {2}, das Zeichen kehrt):": "<0>Od którego wyrazu</0> zachodzi {1}? Rozwiązać nierówność za pomocą logarytmu (uwaga: {2}, znak nierówności się odwraca):",
"{0}: <1>exponentieller Zerfall</1>, Abnahme um {2} pro Schritt.": "{0}: <1>zanik wykładniczy</1>, spadek o {2} na krok.",
"<0>Gefragt:</0> Wie viel ist nach {1} Halbwertszeiten noch vorhanden? Ab welchem Glied ist es höchstens noch {2} mg?": "<0>Pytanie:</0> Ile zostaje po {1} okresach półtrwania? Od którego wyrazu zostaje najwyżej {2} mg?",
"Von einem radioaktiven Stoff sind anfangs {0} mg vorhanden. Nach jeder Halbwertszeit ist nur noch die Hälfte übrig. {1} = Menge in mg nach {2} Halbwertszeiten.": "Na początku jest {0} mg substancji promieniotwórczej. Po każdym okresie półtrwania zostaje tylko połowa. {1} = ilość w mg po {2} okresach półtrwania.",
"{0}: Die Vorzeichen wechseln ab (alternierende Folge).": "{0}: znaki się zmieniają (ciąg naprzemienny).",
"<0>Ausgeschrieben</0> (die ersten {1} und die letzten {2} Summanden):": "<0>W rozwinięciu</0> (pierwsze składniki: {1}, ostatnie: {2}):",
"<0>Indexverschiebung:</0> Mit {1} läuft {2} von {3} bis {4}; der Wert der Summe bleibt gleich.": "<0>Przesunięcie wskaźnika:</0> przy {1} wskaźnik {2} przebiega od {3} do {4}; wartość sumy się nie zmienia.",
"Jeder Summand ist das {0}-fache des vorherigen (geometrische Reihe). Formel: {1}.": "Każdy składnik powstaje z poprzedniego przez pomnożenie przez {0} (szereg geometryczny). Wzór: {1}.",
