"<0>Gefragt:</0> Wie viele Plätze hat der Saal mit {1} Reihen insgesamt?": "<0>Pytanie:</0> Ile miejsc ma łącznie sala, w której liczba rzędów wynosi {1}?",
"Ein Kinosaal hat in der ersten Reihe {0} Plätze, jede weitere Reihe hat {1} Plätze mehr.": "Sala kinowa ma w pierwszym rzędzie {0} miejsc, a każdy następny rząd ma o {1} więcej.",
"<0>Herleitung:</0> {1} – fast alle Summanden heben sich weg: {2}.": "<0>Wyprowadzenie:</0> {1} – prawie wszystkie składniki się znoszą: {2}.",
"<0>Geometrische Reihe:</0> Summe der ersten {1} Glieder von {2}.": "<0>Szereg geometryczny:</0> suma początkowych wyrazów ciągu {2} (liczba wyrazów: {1}).",
"<0>Gefragt:</0> Wie viele Reiskörner liegen auf den ersten {1} Feldern zusammen?": "<0>Pytanie:</0> Ile ziaren ryżu leży łącznie na początkowych polach (liczba pól: {1})?",
"Legende vom Schachbrett: Auf das erste Feld legt man {0} Reiskorn, auf jedes weitere Feld doppelt so viele wie auf das vorherige. Ein Schachbrett hat {1} Felder.": "Legenda o szachownicy: na pierwszym polu kładzie się {0} ziarno ryżu, a na każdym następnym dwa razy więcej niż na poprzednim. Szachownica ma {1} pola.",
"Geometrische Reihe": "Szereg geometryczny",
"<0>Gefragt:</0> Wie viele km hat er nach {1} Teilstrecken zurückgelegt?": "<0>Pytanie:</0> Ile km zostało przebyte po {1} odcinkach?",
"Jemand geht die Hälfte eines {0} km langen Weges, dann die Hälfte des restlichen Weges, dann wieder die Hälfte des Rests und so weiter.": "Ktoś przechodzi połowę drogi o długości {0} km, potem połowę pozostałej drogi, potem znów połowę reszty i tak dalej.",
"<0>Divergent:</0> Die Glieder werden beliebig gross.": "<0>Rozbieżny:</0> wyrazy stają się dowolnie duże.",
"divergent": "rozbieżny",
"keine Annäherung an eine Zahl: divergent": "nie zbliża się do żadnej liczby: rozbieżny",
"<0>Divergent:</0> Die Glieder springen hin und her und nähern sich keiner festen Zahl.": "<0>Rozbieżny:</0> wyrazy skaczą tam i z powrotem i nie zbliżają się do żadnej ustalonej liczby.",
"Für {0} geht {1}, also nähern sich die Partialsummen einem Grenzwert:": "Dla {0} zachodzi {1}, więc sumy częściowe zbliżają się do granicy:",
