"Unendliche geometrische Reihe": "Nieskończony szereg geometryczny",
"<0>Gefragt:</0> Gegen welchen Wert strebt der zurückgelegte Weg? Kommt er je am Ziel an?": "<0>Pytanie:</0> Do jakiej wartości dąży przebyta droga? Czy kiedykolwiek osiąga się cel?",
"divergent, weil {0}": "rozbieżny, ponieważ {0}",
"Für {0} geht {1} nicht gegen {2}: Die Reihe hat <3>keinen</3> Grenzwert (divergent).": "Dla {0} wyrażenie {1} nie dąży do {2}: szereg <3>nie</3> ma granicy (rozbieżny).",
"Die Vermutung ist falsch – ein einziges Gegenbeispiel genügt.": "Hipoteza jest fałszywa – wystarczy jeden kontrprzykład.",
"Aber für {0}:": "Ale dla {0}:",
"<0>Beispiele beweisen nichts.</0> Die Werte von {1} sind für {2} alles Primzahlen:": "<0>Przykłady niczego nie dowodzą.</0> Wartości {1} dla {2} to same liczby pierwsze:",
