"Die Reihe rückwärts darunter schreiben: Jede Spalte ergibt {0}, und es sind {1} Spalten. Das ist die Summe zweimal, also s = {2} · {3} / {4}. Dieselbe Idee steckt in der Formel sₙ = n · (a₁ + aₙ) / {5}.": "Zapisać szereg od końca poniżej: każda kolumna daje {0}, a liczba kolumn wynosi {1}. To jest suma liczona dwukrotnie, więc s = {2} · {3} / {4}. Ta sama idea kryje się we wzorze sₙ = n · (a₁ + aₙ) / {5}.",
"Der Legende nach stellte der Lehrer Büttner um {0} seiner Klasse die Aufgabe, alle Zahlen von {1} bis {2} zu addieren – er wollte eine Weile Ruhe. Der neunjährige Carl Friedrich Gauss war nach wenigen Augenblicken fertig:": "Według legendy około roku {0} nauczyciel Büttner zadał klasie dodanie wszystkich liczb od {1} do {2} – chciał mieć chwilę spokoju. Dziewięcioletni Carl Friedrich Gauss skończył po kilku chwilach:",
"Der kleine Gauss": "Mały Gauss",
"Intervall:": "Przedział:",
"Das Intervall ist <0>beschränkt</0>; seine Länge ist {1}.": "Przedział jest <0>ograniczony</0>; jego długość wynosi {1}.",
"Ein <0>Intervall</0> ist die Menge aller reellen Zahlen zwischen zwei Randpunkten. Eckige Klammer {1}: Randpunkt gehört dazu; runde Klammer {2}: gehört nicht dazu. Bei {3} ist die Klammer immer offen.": "<0>Przedział</0> to zbiór wszystkich liczb rzeczywistych między dwoma końcami. Nawias kwadratowy {1}: koniec należy do przedziału; nawias okrągły {2}: nie należy. Przy {3} nawias jest zawsze otwarty.",
"Intervall und Schreibweisen": "Przedział i zapisy",
"Rechenweg: Intervall": "Tok rozwiązania: Przedział",
"gefüllter Punkt: Rand gehört dazu, leerer Punkt: gehört nicht dazu": "kropka zamalowana: koniec należy, kropka pusta: nie należy",
"Mengenschreibweise:": "Zapis zbiorowy:",
"Ungleichung:": "Nierówność:",
"Intervallschreibweise:": "Zapis przedziałowy:",
"dazugehören": "należą do niego",
"Randpunkte": "końce",
"Ziehe die {0} auf der Zahlengeraden und lege links fest, ob sie {1} oder bis ±∞ reichen: Das {2} erscheint in Intervallschreibweise, als Ungleichung und in Mengenschreibweise.": "Przeciągaj {0} na osi liczbowej i ustal po lewej, czy {1}, czy sięgają do ±∞: {2} pojawia się w zapisie przedziałowym, jako nierówność i w zapisie zbiorowym.",
"{0} Ziehe die Randpunkte im Bild. Links wählst du offen oder geschlossen, unendlich und die Operation; rechts steht der Rechenweg.": "{0} Przeciągaj końce na rysunku. Po lewej wybierasz: otwarty lub domknięty, nieskończony oraz działanie; po prawej znajduje się tok rozwiązania.",
"Alle Operationen auf einen Blick:": "Wszystkie działania w skrócie:",
"<0>Vorgehen:</0> Beide Intervalle untereinander auf der Zahlengeraden einzeichnen, die gesuchten Bereiche ablesen und bei jedem Randpunkt prüfen, ob er dazugehört.": "<0>Sposób postępowania:</0> narysować oba przedziały jeden pod drugim na osi liczbowej, odczytać szukane części i przy każdym końcu sprawdzić, czy należy.",
"Die <0>Schnittmenge</0> {1} enthält alle Zahlen, die in {2} <3>und</3> in {4} liegen.": "<0>Część wspólna</0> {1} zawiera wszystkie liczby, które leżą w {2} <3>i</3> w {4}.",
"Rechenweg: Mengenoperation": "Tok rozwiązania: Działanie na zbiorach",
