"Intervall A": "Przedział A",
"Ā (Komplement von A)": "Ā (dopełnienie A)",
"B \\ A (Differenz)": "B \\ A (różnica)",
"A \\ B (Differenz)": "A \\ B (różnica)",
"A ∪ B (Vereinigung)": "A ∪ B (suma)",
"A ∩ B (Schnittmenge)": "A ∩ B (część wspólna)",
"Operation": "Działanie",
"Mit Intervallen rechnet man wie mit Mengen: A ∩ B (und), A ∪ B (oder), A \\ B (ohne) und das Komplement Ā (alle anderen reellen Zahlen). Am einfachsten zeichnet man beide Intervalle untereinander und liest das Ergebnis ab; an jedem Randpunkt entscheidet man, ob er dazugehört.": "Na przedziałach wykonuje się działania jak na zbiorach: A ∩ B (i), A ∪ B (lub), A \\ B (bez) oraz dopełnienie Ā (wszystkie pozostałe liczby rzeczywiste). Najprościej narysować oba przedziały jeden pod drugim i odczytać wynik; przy każdym końcu rozstrzyga się, czy należy.",
"Ergebnismenge": "zbiór wynikowy",
"Ziehe die Randpunkte von {0} und {1} und wähle eine Operation: Die {2} zeigt, welche Zahlen in A und B liegen (Schnittmenge), in A oder B (Vereinigung), in A, aber nicht in B (Differenz) oder nicht in A (Komplement).": "Przeciągaj końce przedziałów {0} i {1} i wybierz działanie: {2} pokazuje, które liczby leżą w A i B (część wspólna), w A lub B (suma), w A, ale nie w B (różnica), albo nie w A (dopełnienie).",
"<0>Schritt für Schritt</0> (zuerst die Klammern):": "<0>Krok po kroku</0> (najpierw nawiasy):",
"alle Elemente": "wszystkie elementy",
