"Mit der Computertastatur: u = ∪, n = ∩, − = \\, ' = Komplement.": "Z klawiatury komputera: u = ∪, n = ∩, − = \\, ' = dopełnienie.",
"Eingabe löschen": "Wyczyść wpis",
"Zeichen löschen": "Usuń znak",
"Komplement: nach der Menge oder Klammer drücken (oder zuerst markieren)": "Dopełnienie: naciśnij po zbiorze lub nawiasie (albo najpierw zaznacz)",
