"Mengen": "Zbiory",
"Mengen und Term": "Zbiory i wyrażenie",
"Vereinigung A ∪ B: in A oder B. Schnitt A ∩ B: in A und B. Differenz A \\ B: in A, aber nicht in B. Komplement Ā: in G, aber nicht in A. Bei drei Mengen gibt es acht Felder; man füllt sie von der Mitte nach aussen. Gesetze von De Morgan: (A ∪ B)‾ = Ā ∩ B̄ und (A ∩ B)‾ = Ā ∪ B̄.": "Suma A ∪ B: w A lub B. Część wspólna A ∩ B: w A i B. Różnica A \\ B: w A, ale nie w B. Dopełnienie Ā: w G, ale nie w A. Przy trzech zbiorach jest osiem obszarów; wypełnia się je od środka na zewnątrz. Prawa De Morgana: (A ∪ B)‾ = Ā ∩ B̄ oraz (A ∩ B)‾ = Ā ∪ B̄.",
"Grundmenge G": "zbiór uniwersalny G",
"Feldern": "obszarach",
"schraffierten Felder": "zakreskowane obszary",
"Wähle links eine Operation oder tippe einen Term wie (A ∪ B) ∩ C: Die {0} bilden die Ergebnismenge («{1} Term Schritt für Schritt schraffieren» baut sie von innen nach aussen auf). Mit Elementen oder Anzahlen in den {2} liest du das Ergebnis direkt ab; die Mengen {3}, {4} und {5} liegen in der {6}.": "Wybierz po lewej działanie albo wpisz wyrażenie, np. (A ∪ B) ∩ C: {0} tworzą zbiór wynikowy („{1} Zakreskuj wyrażenie krok po kroku” buduje go od środka na zewnątrz). Z elementami lub liczebnościami w {2} odczytasz wynik bezpośrednio; zbiory {3}, {4} i {5} zawiera {6}.",
"Tipp: Zuerst die Klammern. Ein Feld gehört dazu, wenn seine Punkte die Bedingung erfüllen.": "Wskazówka: najpierw nawiasy. Obszar należy do zbioru, jeśli jego punkty spełniają warunek.",
"Schraffiere": "Zakreskuj",
"Auswahl löschen": "Wyczyść zaznaczenie",
"Klicke im Bild auf ein Feld, um es zu schraffieren; nochmals klicken entfernt die Schraffur.": "Kliknij obszar na rysunku, aby go zakreskować; ponowne kliknięcie usuwa kreskowanie.",
"Schraffiere {0}: Klicke im Venn-Diagramm die Felder an.": "Zakreskuj {0}: klikaj obszary na diagramie Venna.",
"Anzahlen im Venn-Diagramm ({0} Mengen)": "Liczebności na diagramie Venna ({0} zbiory)",
"Elemente bestimmen": "Wyznacz elementy",
"Venn-Diagramm schraffieren": "Zakreskuj diagram Venna",
"Intervall schreiben": "Zapisz przedział",
"Aufgabe": "Zadanie",
"Übungen zu Intervallen (Schreibweisen, Schnitt, Vereinigung, Differenz, Komplement) und zu Mengenoperationen mit zwei oder drei Mengen im Venn-Diagramm. Jede Aufgabe wird neu erzeugt; «Lösung zeigen» zeigt den Weg.": "Ćwiczenia z przedziałów (zapisy, część wspólna, suma, różnica, dopełnienie) oraz z działań na dwóch lub trzech zbiorach na diagramie Venna. Każde zadanie jest tworzone na nowo; „Pokaż rozwiązanie” pokazuje sposób.",
"Venn-Diagramm": "diagram Venna",
"Wähle links die Aufgabenart und löse die Aufgabe: Tippe die Antwort ein oder klicke im {0} die Felder an, die zur Menge gehören. «Prüfen» zeigt, ob es stimmt; danach steht rechts der Lösungsweg.": "Wybierz po lewej rodzaj zadania i rozwiąż je: wpisz odpowiedź albo kliknij na rysunku ({0}) obszary należące do zbioru. „Sprawdź” pokazuje, czy jest dobrze; potem po prawej znajduje się rozwiązanie.",
"Übungen: Aufgabenart wählen, Antwort eintippen oder Felder anklicken, dann «Prüfen». «Lösung zeigen» und «Neue Aufgabe» stehen daneben.": "Ćwiczenia: wybierz rodzaj zadania, wpisz odpowiedź albo kliknij obszary, potem „Sprawdź”. „Pokaż rozwiązanie” i „Nowe zadanie” znajdują się obok.",
"Venn-Diagramm: Operation wählen oder einen eigenen Term mit den Tasten A, B, ∪, ∩, \\ und Ā eingeben; {0} oder {1} Mengen, Felder mit Elementen oder Anzahlen.": "Diagram Venna: wybierz działanie albo wpisz własne wyrażenie klawiszami A, B, ∪, ∩, \\ i Ā; {0} lub {1} zbiory, obszary z elementami lub liczebnościami.",
"Die Schreibweise offener Intervalle ist wählbar: runde Klammer (a, b) oder nach aussen gedrehte eckige Klammer.": "Zapis przedziałów otwartych można wybrać: nawias okrągły (a, b) albo nawias kwadratowy odwrócony na zewnątrz.",
"Randpunkte auf der Zahlengeraden ziehen; links legst du fest, ob ein Rand dazugehört («gehört dazu») oder das Intervall bis −∞ bzw. ∞ reicht.": "Przeciągaj końce na osi liczbowej; po lewej ustalasz, czy koniec należy („należy”), czy przedział sięga do −∞ lub ∞.",
"Das Intervall ist <0>unbeschränkt</0> (es reicht bis ins Unendliche).": "Przedział jest <0>nieograniczony</0> (sięga do nieskończoności).",
"Ein <0>Intervall</0> ist die Menge aller reellen Zahlen zwischen zwei Randpunkten. Eckige Klammer {1}: Randpunkt gehört dazu; nach aussen gedreht {2}: gehört nicht dazu. Bei {3} ist die Klammer immer offen.": "<0>Przedział</0> to zbiór wszystkich liczb rzeczywistych między dwoma końcami. Nawias kwadratowy {1}: koniec należy do przedziału; nawias odwrócony na zewnątrz {2}: nie należy. Przy {3} nawias jest zawsze otwarty.",
"Mengenoperation": "Działanie na zbiorach",
"Das Ergebnis besteht aus {0} getrennten Teilen.": "Wynik składa się z {0} oddzielnych części.",
"Die <0>Vereinigungsmenge</0> {1} enthält alle Zahlen, die in {2} <3>oder</3> in {4} (oder in beiden) liegen.": "<0>Suma</0> {1} zawiera wszystkie liczby, które leżą w {2} <3>lub</3> w {4} (albo w obu).",
"Die <0>Differenzmenge</0> {1} enthält alle Zahlen aus {2}, die <3>nicht</3> in {4} liegen.": "<0>Różnica</0> {1} zawiera wszystkie liczby z {2}, które <3>nie</3> leżą w {4}.",
"Das <0>Komplement</0> {1} enthält alle reellen Zahlen, die <2>nicht</2> in {3} liegen.": "<0>Dopełnienie</0> {1} zawiera wszystkie liczby rzeczywiste, które <2>nie</2> leżą w {3}.",
"Die Intervalle haben keine gemeinsamen Zahlen: Das Ergebnis ist die leere Menge.": "Przedziały nie mają wspólnych liczb: wynikiem jest zbiór pusty.",
"<0>Differenz</0> {1}: alle Elemente von {2}, die <3>nicht</3> in {4} liegen.": "<0>Różnica</0> {1}: wszystkie elementy zbioru {2}, które <3>nie</3> leżą w {4}.",
"Gesetze von De Morgan: {0} und {1}.": "Prawa De Morgana: {0} oraz {1}.",
"<0>Komplement</0> {1}: alle Elemente der Grundmenge {2}, die nicht in {3} liegen.": "<0>Dopełnienie</0> {1}: wszystkie elementy zbioru uniwersalnego {2}, które nie leżą w {3}.",
