"Beide Schreibweisen gehen: [−{0}, {1}) oder [−{2}; {3}[. Für ∞, ∪ und ∅ die Tasten benutzen.": "Oba zapisy są poprawne: [−{0}, {1}) lub [−{2}; {3}[. Do ∞, ∪ i ∅ użyj klawiszy.",
