"Nicht lesbar. Beispiele: [−{0}, {1}) oder ]−{2}; {3}[ oder (−∞, {4}] ∪ [{5}, ∞)": "Nie da się odczytać. Przykłady: [−{0}, {1}) lub ]−{2}; {3}[ lub (−∞, {4}] ∪ [{5}, ∞)",
"Bei ±∞ ist die Klammer immer offen.": "Przy ±∞ nawias jest zawsze otwarty.",
"Noch nicht richtig. Zeichne die Intervalle auf der Zahlengeraden.": "Jeszcze nie jest dobrze. Narysuj przedziały na osi liczbowej.",
"Die Grenzen stimmen, aber prüfe, ob die Randpunkte dazugehören.": "Końce się zgadzają, ale sprawdź, czy należą do przedziału.",
"Randpunkte ablesen; eckige Klammer nach innen, wenn der Randpunkt dazugehört (gefüllter Punkt, {0}), sonst runde (oder nach aussen gedrehte) Klammer. Bei {1} immer offen.": "Odczytać końce; nawias kwadratowy do środka, jeśli koniec należy (kropka zamalowana, {0}), w przeciwnym razie nawias okrągły (lub odwrócony na zewnątrz). Przy {1} zawsze otwarty.",
"Schritt für Schritt von innen nach aussen (zuerst die Klammern):": "Krok po kroku od środka na zewnątrz (najpierw nawiasy):",
