"Ebene": "Płaszczyzna",
"Gib links eine {0} in Koordinatenform ein (z. B. {1}x + {2}y − z = {3}) und drehe den Raum mit der Maus: {4} und {5} zeigen, wo sie die Achsen und Koordinatenebenen trifft. Mit zwei oder drei Ebenen erscheinen {6} und {7}.": "Wpisz po lewej równanie w postaci ogólnej ({0}), np. {1}x + {2}y − z = {3}, i obracaj przestrzeń myszą: {4} i {5} pokazują, gdzie płaszczyzna przecina osie i płaszczyzny układu. Przy dwóch lub trzech płaszczyznach pojawiają się {6} i {7}.",
"{0} Ziehe im Bild, um den Raum zu drehen; oben links wählst du die Ansicht, rechts steht der Rechenweg.": "{0} Przeciągaj na rysunku, aby obracać przestrzeń; u góry po lewej wybierasz widok, po prawej znajduje się tok rozwiązania.",
"<0>Mittelpunkt</0> der Strecke {1}: Mittelwert der Koordinaten.": "<0>Środek</0> odcinka {1}: średnia współrzędnych.",
"<0>Länge</0> (Betrag) mit dem Satz des Pythagoras im Raum: Sie ist der Abstand der Punkte {1} und {2}.": "<0>Długość</0> (wartość bezwzględna) z twierdzenia Pitagorasa w przestrzeni: jest to odległość punktów {1} i {2}.",
