"Gib links die Punkte A und B ein und drehe den Raum: Der {0} führt von A nach B; seine {1} sind die Schritte in x-, y- und z-Richtung. Dazu die {2} und der {3}.": "Wpisz po lewej punkty A i B i obracaj przestrzeń: {0} prowadzi od A do B; jego {1} to kroki w kierunkach x, y i z. Do tego {2} i {3}.",
"Ein Punkt {0} hat den Ortsvektor OA. Der Verbindungsvektor ist AB = B − A (Spitze minus Fuss). Seine Länge |AB| = √(v₁² + v₂² + v₃²) ist der Abstand der Punkte, der Mittelpunkt ist M = ½(A + B).": "Punkt {0} ma wektor wodzący OA. Wektor łączący to AB = B − A (koniec minus początek). Jego długość |AB| = √(v₁² + v₂² + v₃²) jest odległością punktów, a środek to M = ½(A + B).",
