"Die Probe stimmt: Die Geraden <0>schneiden</0> sich. {1} in {2} einsetzen:": "Sprawdzenie się zgadza: proste <0>przecinają się</0>. Podstawić {1} do {2}:",
"Aus den Gleichungen (x) und (y) folgt {0}, {1}. <2>{3}. Probe</2> in (z):": "Z równań (x) i (y) wynika {0}, {1}. <2>{3}. Sprawdzenie</2> w (z):",
"Nein: Die Geraden schneiden sich oder sind windschief. <0>{1}. Gleichsetzen:</0> {2} ergibt drei Gleichungen.": "Nie: proste przecinają się albo są skośne. <0>{1}. Przyrównać:</0> {2} daje trzy równania.",
"<0>{1}. Richtungsvektoren vergleichen:</0> Ist {2} ein Vielfaches von {3}?": "<0>{1}. Porównać wektory kierunkowe:</0> czy {2} jest wielokrotnością {3}?",
