"Gib links die Geraden g und h in Parameterform ein und drehe den Raum: Schneiden sie sich im {0}, sind sie parallel oder {1}? Die {2} entscheiden zuerst. Mit den Reglern t und s (oder «{3} t und s laufen lassen») wandern die Punkte {4} und {5} auf den Geraden: Jeder Parameterwert gibt genau einen Punkt.": "Wpisz po lewej proste g i h w postaci parametrycznej i obracaj przestrzeń: czy mają wspólny {0}, są równoległe czy {1}? Najpierw rozstrzygają {2}. Suwakami t i s (albo „{3} Zmieniaj t i s”) punkty {4} i {5} wędrują po prostych: każda wartość parametru daje dokładnie jeden punkt.",
"Gerade in Parameterform: X = P + t·u mit Stützpunkt P und Richtungsvektor u. Zwei Geraden sind identisch, echt parallel, schneidend oder windschief. Prüfen: Sind u und v Vielfache? Sonst gleichsetzen: zwei Gleichungen lösen, die dritte prüfen.": "Prosta w postaci parametrycznej: X = P + t·u z punktem zaczepienia P i wektorem kierunkowym u. Dwie proste pokrywają się, są równoległe różne, przecinają się albo są skośne. Sprawdzić: czy u i v są wielokrotnościami? Jeśli nie, przyrównać: rozwiązać dwa równania, trzecie sprawdzić.",
"Das Skalarprodukt ist positiv: Der Winkel ist <0>spitz</0>.": "Iloczyn skalarny jest dodatni: kąt jest <0>ostry</0>.",
