"Rechenweg: Skalarprodukt und Winkel": "Tok rozwiązania: Iloczyn skalarny i kąt",
"{0} Vektorprodukt a × b zeigen": "{0} Pokaż iloczyn wektorowy a × b",
"Vektorprodukt: a = ({0} | {1} | {2}), b = ({3} | {4} | {5})": "Iloczyn wektorowy: a = ({0} | {1} | {2}), b = ({3} | {4} | {5})",
"Stumpfer Winkel: a = ({0} | {1} | {2}), b = (−{3} | {4} | {5})": "Kąt rozwarty: a = ({0} | {1} | {2}), b = (−{3} | {4} | {5})",
"Senkrecht: a = ({0} | {1} | −{2}), b = ({3} | {4} | {5})": "Prostopadłe: a = ({0} | {1} | −{2}), b = ({3} | {4} | {5})",
"Vektorprodukt a × b": "Iloczyn wektorowy a × b",
"Gib links die Vektoren a und b ein und drehe den Raum: Der {0} zwischen ihnen folgt aus dem Skalarprodukt. Ist a · b = {1}, stehen sie senkrecht. Das {2} steht senkrecht auf beiden.": "Wpisz po lewej wektory a i b i obracaj przestrzeń: {0} między nimi wynika z iloczynu skalarnego. Jeśli a · b = {1}, są prostopadłe. {2} jest prostopadły do obu.",
"Skalarprodukt: a · b = a₁b₁ + a₂b₂ + a₃b₃ = |a|·|b|·cos φ. Daraus der Winkel: cos φ = a · b / (|a|·|b|). Senkrecht genau dann, wenn a · b = {0}. Vektorprodukt a × b: senkrecht zu a und b, Länge = Fläche des Parallelogramms.": "Iloczyn skalarny: a · b = a₁b₁ + a₂b₂ + a₃b₃ = |a|·|b|·cos φ. Stąd kąt: cos φ = a · b / (|a|·|b|). Prostopadłe dokładnie wtedy, gdy a · b = {0}. Iloczyn wektorowy a × b: prostopadły do a i b, długość = pole równoległoboku.",
"<0>Lotfusspunkt:</0> Vom Punkt {1} aus in Richtung {2} bis zur Ebene: {3}.": "<0>Spodek prostopadłej:</0> od punktu {1} w kierunku {2} aż do płaszczyzny: {3}.",
"Ebene {0} mit Normalenvektor {1}, {2}. <3>Hessesche Normalform:</3> Punkt einsetzen und durch {4} teilen.": "Płaszczyzna {0} z wektorem normalnym {1}, {2}. <3>Postać normalna Hessego:</3> podstawić punkt i podzielić przez {4}.",
"Abstand Punkt–Ebene": "Odległość punkt–płaszczyzna",
"Rechenweg: Abstände: Punkt–Ebene, Punkt–Gerade": "Tok rozwiązania: Odległości: punkt–płaszczyzna, punkt–prosta",
"Ebene E": "Płaszczyzna E",
"Punkt–Gerade": "Punkt–prosta",
