"Lotfusspunkt F": "Spodek prostopadłej F",
"Abstand d": "Odległość d",
"Gib links den Punkt X und die Ebene oder Gerade ein und drehe den Raum: Der {0} ist die Länge des Lots vom Punkt X zum {1}.": "Wpisz po lewej punkt X oraz płaszczyznę lub prostą i obracaj przestrzeń: {0} to długość prostopadłej poprowadzonej z punktu X; jej koniec to {1}.",
"Abstand Punkt–Ebene mit der Hesseschen Normalform: d = |a·x₀ + b·y₀ + c·z₀ − d| / |n|. Abstand Punkt–Gerade: Lotfusspunkt F auf der Geraden so, dass XF senkrecht zum Richtungsvektor steht, dann d = |XF|.": "Odległość punkt–płaszczyzna z postaci normalnej Hessego: d = |a·x₀ + b·y₀ + c·z₀ − d| / |n|. Odległość punkt–prosta: spodek prostopadłej F na prostej taki, że XF jest prostopadły do wektora kierunkowego; wtedy d = |XF|.",
"{0} schneidet die Kugel in einem <1>Schnittkreis</1> mit Mittelpunkt {2} (Lotfusspunkt von {3}) und Radius": "{0} przecina sferę wzdłuż <1>okręgu przecięcia</1> o środku {2} (spodek prostopadłej z {3}) i promieniu",
"<0>Lage der Ebene</0> {1}: Abstand des Mittelpunkts zur Ebene (Hessesche Normalform).": "<0>Położenie płaszczyzny</0> {1}: odległość środka od płaszczyzny (postać normalna Hessego).",
"{0} liegt <1>auf</1> der Kugel.": "{0} leży <1>na</1> sferze.",
"<0>Lage des Punktes</0> {1}: Abstand zum Mittelpunkt mit dem Radius {2} vergleichen.": "<0>Położenie punktu</0> {1}: porównać odległość od środka z promieniem {2}.",
"Rechenweg: Kugel": "Tok rozwiązania: Sfera",
"{0} Ebene zeigen": "{0} Pokaż płaszczyznę",
"Radius r": "Promień r",
"Kugel, Punkt, Ebene": "Sfera, punkt, płaszczyzna",
"Punkt innen: {0}, r = {1}, {2}": "Punkt wewnątrz: {0}, r = {1}, {2}",
"Ebene verfehlt die Kugel": "Płaszczyzna nie przecina sfery",
"Tangentialebene: {0}, r = {1}, E: z = {2}": "Płaszczyzna styczna: {0}, r = {1}, E: z = {2}",
"{0}, r = {1}; Ebene z = {2} schneidet": "{0}, r = {1}; płaszczyzna z = {2} przecina",
"Schnittkreis": "Okrąg przecięcia",
"Punkt X": "Punkt X",
"Gib links Mittelpunkt und Radius ein und drehe den Raum: Liegt der {0} innen, auf oder ausserhalb der {1}? Die {2} schneidet sie in einem {3}, berührt sie oder verfehlt sie.": "Wpisz po lewej środek i promień i obracaj przestrzeń: czy {0} leży wewnątrz, na powierzchni czy na zewnątrz ({1})? {2} przecina ją – wtedy powstaje {3} – dotyka jej albo jej nie przecina.",
"Kugel mit Mittelpunkt {0} und Radius r: (x − m₁)² + (y − m₂)² + (z − m₃)² = r². Lage eines Punktes: Abstand zu M mit r vergleichen. Lage einer Ebene: Abstand d von M zur Ebene; für d {1} r Schnittkreis mit Radius √(r² − d²).": "Sfera o środku {0} i promieniu r: (x − m₁)² + (y − m₂)² + (z − m₃)² = r². Położenie punktu: porównać odległość od M z r. Położenie płaszczyzny: odległość d punktu M od płaszczyzny; dla d {1} r okrąg przecięcia o promieniu √(r² − d²).",
"In den anderen Ansichten gibst du Punkte, Vektoren und Geraden links als Koordinaten ein; die Beispiele füllen die Felder aus.": "W pozostałych widokach wpisujesz po lewej punkty, wektory i proste jako współrzędne; przykłady wypełniają pola.",
"Ebenen entdecken: Gleichung eintippen und «+ Ebene». Buchstaben wie a, b, c, d in der Gleichung werden zu Schiebereglern.": "Odkrywanie płaszczyzn: wpisz równanie i naciśnij „+ Płaszczyzna”. Litery takie jak a, b, c, d w równaniu stają się suwakami.",
"«Von oben», «Von vorn» und «Von der Seite» zeigen die Risse; «Bereich ±» legt fest, wie weit die Achsen reichen.": "„Z góry”, „Z przodu” i „Z boku” pokazują rzuty; „Zakres ±” ustala, jak daleko sięgają osie.",
"Raum drehen: im Bild ziehen. Mausrad zoomt, Umschalt+Ziehen verschiebt, Doppelklick stellt die Standardansicht her.": "Obracanie przestrzeni: przeciągaj na rysunku. Kółko myszy powiększa, Shift+przeciąganie przesuwa, dwukrotne kliknięcie przywraca widok standardowy.",
"Ortsvektoren zeigen": "Pokaż wektory wodzące",
