"Widerspruch: Die Geraden sind <0>windschief</0> (nicht parallel und ohne Schnittpunkt).": "Sprzeczność: proste są <0>skośne</0> (nie są równoległe i nie mają punktu wspólnego).",
"Aus den Gleichungen (y) und (z) folgt {0}, {1}. <2>{3}. Probe</2> in (x):": "Z równań (y) i (z) wynika {0}, {1}. <2>{3}. Sprawdzenie</2> w (x):",
"{0} und {1} sind echt parallel.": "{0} i {1} są równoległe różne.",
"Nein, {0} liegt nicht auf {1}: Die Geraden sind <2>echt parallel</2>. Ihr Abstand ist {3}.": "Nie, {0} nie leży na {1}: proste są <2>równoległe różne</2>. Ich odległość wynosi {3}.",
"Ja: {0}. Die Geraden sind parallel oder identisch. <1>{2}. Punktprobe:</1> Liegt {3} auf {4}?": "Tak: {0}. Proste są równoległe lub pokrywają się. <1>{2}. Sprawdzenie punktu:</1> czy {3} leży na {4}?",
"{0} und {1} sind identisch.": "{0} i {1} pokrywają się.",
"Ja, {0} liegt auf {1}: Die Geraden sind <2>identisch</2>.": "Tak, {0} leży na {1}: proste <2>pokrywają się</2>.",
"Punkte X (auf g) und Y (auf h) zeigen": "Pokaż punkty X (na g) i Y (na h)",
"Das Skalarprodukt ist {0}: Die Vektoren stehen <1>senkrecht</1> aufeinander.": "Iloczyn skalarny jest równy {0}: wektory są do siebie <1>prostopadłe</1>.",
"Das Skalarprodukt ist negativ: Der Winkel ist <0>stumpf</0>.": "Iloczyn skalarny jest ujemny: kąt jest <0>rozwarty</0>.",
"<0>Vektorprodukt:</0> steht senkrecht auf {1} und {2}; seine Länge ist die Fläche des Parallelogramms.": "<0>Iloczyn wektorowy:</0> jest prostopadły do {1} i {2}; jego długość to pole równoległoboku.",
"Vektorprodukt a × b zeigen": "Pokaż iloczyn wektorowy a × b",
"<0>Lotfusspunkt</0> {1}: Der Vektor {2} muss senkrecht auf {3} stehen, also {4}.": "<0>Spodek prostopadłej</0> {1}: wektor {2} musi być prostopadły do {3}, czyli {4}.",
"{0} ist eine <1>Tangentialebene</1>; sie berührt die Kugel im Punkt {2}.": "{0} jest <1>płaszczyzną styczną</1>; dotyka sfery w punkcie {2}.",
