"Ausgezeichnet – das sitzt.": "Znakomicie – to masz opanowane.",
"Gut gemacht. Schau dir unten an, was noch nicht stimmt.": "Dobra robota. Zobacz poniżej, co jeszcze się nie zgadza.",
"Ein guter Anfang. Die Begründungen unten zeigen, wo es noch hakt.": "Dobry początek. Uzasadnienia poniżej pokazują, gdzie jeszcze są trudności.",
"Da ist noch Luft nach oben. Arbeite die Ansicht nochmals durch und lies die Begründungen unten.": "Jest jeszcze nad czym popracować. Przejdź widok jeszcze raz i przeczytaj uzasadnienia poniżej.",
"richtig beantwortet": "poprawna odpowiedź",
