"Deine Antwort:": "Twoja odpowiedź:",
"Richtig ist:": "Poprawna odpowiedź:",
"Die Fragen gibt es nur auf Deutsch.": "Pytania są dostępne tylko po niemiecku.",
"Marchzins: Zeitstrahl und Konten": "Odsetki proporcjonalne: oś czasu i konta",
"Trage links jede {0} mit ihrem Datum ein: Jede liegt auf einem {1} und trägt Marchzins bis zum {2}. Die {3} zeigt Zinstage und Zins je Konto, am Schluss werden {4}. «{5} Zinsen wachsen lassen» zeigt, wie der Zins Tag für Tag dazukommt.": "Po lewej wpisz każdą {0} z jej datą: każda leży na {1} i przynosi odsetki proporcjonalne do {2}. {3} pokazuje dni odsetkowe i odsetki dla każdego konta, na końcu {4}. «{5} Pozwól odsetkom rosnąć» pokazuje, jak odsetki przybywają dzień po dniu.",
"Ein- oder Auszahlung": "wpłatę lub wypłatę",
"eigenen Konto": "osobnym koncie",
"Stichtag": "dnia zamknięcia",
"Tabelle": "Tabela",
"Kapital und Zinsen addiert": "kapitał i odsetki się dodaje",
"Prinzip der verschiedenen Konti beim Marchzins: Der Saldo am Jahresanfang und jede Ein- oder Auszahlung werden wie ein eigenes Konto behandelt. Jedes trägt Zins für seine Zinstage bis zum Stichtag (Monat = {0} Tage, Jahr = {1} Tage). Eine Auszahlung zählt als Konto mit negativem Betrag, ihr Zins wird abgezogen. Kapital und Zinsen zusammen ergeben den Saldo am Stichtag.": "Zasada osobnych kont przy odsetkach proporcjonalnych: saldo na początku roku oraz każdą wpłatę lub wypłatę traktuje się jak osobne konto. Każde przynosi odsetki za swoje dni odsetkowe do dnia zamknięcia (miesiąc = {0} dni, rok = {1} dni). Wypłata liczy się jako konto z kwotą ujemną, jej odsetki się odejmuje. Kapitał i odsetki razem dają saldo w dniu zamknięcia.",
