"Zeitstrahl eines Jahres: Einzahlungen oben, Auszahlungen unten (Klick auf einen Monat: Zahlung hinzufügen)": "Oś czasu jednego roku: wpłaty u góry, wypłaty u dołu (kliknij miesiąc, aby dodać płatność)",
