"positive reelle Achse:": "dodatnia półoś rzeczywista:",
"{0} hat den Betrag {1} und das Argument {2}": "{0} ma moduł {1} i argument {2}",
"<0>Konjugierte Zahl:</0> {1} hat denselben Realteil und den entgegengesetzten Imaginärteil. Das Produkt {2} ist reell.": "<0>Liczba sprzężona:</0> {1} ma tę samą część rzeczywistą i przeciwną część urojoną. Iloczyn {2} jest rzeczywisty.",
"<0>Polarform:</0> Mit dem Betrag {1} und dem Winkel {2} gilt {3} und {4}.": "<0>Postać trygonometryczna:</0> dla modułu {1} i kąta {2} zachodzi {3} oraz {4}.",
"<0>Argument:</0> Der Winkel {1} wird von der positiven reellen Achse aus im Gegenuhrzeigersinn gemessen. Der Taschenrechner liefert aus {2} nur Winkel zwischen {3} und {4}; der Quadrant von {5} entscheidet, was dazukommt.": "<0>Argument:</0> kąt {1} mierzy się od dodatniej półosi rzeczywistej przeciwnie do ruchu wskazówek zegara. Z {2} kalkulator podaje tylko kąty między {3} a {4}; o tym, co trzeba dodać, decyduje ćwiartka, w której leży {5}.",
"<0>Betrag:</0> Der Zeiger ist die Hypotenuse eines rechtwinkligen Dreiecks mit den Katheten {1} und {2} (Satz des Pythagoras).": "<0>Moduł:</0> strzałka jest przeciwprostokątną trójkąta prostokątnego o przyprostokątnych {1} i {2} (twierdzenie Pitagorasa).",
"<0>Normalform:</0> {1} mit dem Realteil {2} und dem Imaginärteil {3}; für die imaginäre Einheit gilt {4}.": "<0>Postać algebraiczna:</0> {1} z częścią rzeczywistą {2} i częścią urojoną {3}; dla jednostki urojonej zachodzi {4}.",
"konjugierte Zahl": "liczba sprzężona",
"Argument φ": "argument φ",
"Imaginärteil": "część urojona",
"Realteil": "część rzeczywista",
"Betrag von z": "Moduł liczby z",
"Zahl z": "liczbę z",
"Ziehe die {0} in der Gauss-Ebene: Ihr {1} ist die Koordinate nach rechts, ihr {2} die Koordinate nach oben. Der {3} ist die Länge des Zeigers, das {4} sein Winkel zur positiven reellen Achse. Die {5} liegt gespiegelt an der reellen Achse.": "Przeciągnij {0} na płaszczyźnie zespolonej: jej {1} to współrzędna w prawo, a {2} to współrzędna w górę. {3} jest długością strzałki, a {4} jej kątem z dodatnią półosią rzeczywistą. Symetrycznie względem osi rzeczywistej leży {5}.",
"{0} Ziehe die farbigen Punkte in der Gauss-Ebene: Zeiger, Winkel und Rechenweg rechnen mit. Links wählst du die Ansicht.": "{0} Przeciągaj kolorowe punkty na płaszczyźnie zespolonej: strzałki, kąty i tok obliczeń zmieniają się razem z nimi. Widok wybierasz po lewej.",
"liegt auf der imaginären Achse": "leży na osi urojonej",
"Für {0} ist kein Winkel festgelegt.": "Dla {0} kąt nie jest określony.",
"Mit diesen Werten lässt sich kein Bild zeichnen.": "Dla tych wartości nie da się narysować rysunku.",
"Eine komplexe Zahl z = a + bi besteht aus zwei reellen Zahlen: dem Realteil a und dem Imaginärteil b. Die imaginäre Einheit i erfüllt i² = −{0}. Man zeichnet z als Punkt (a | b) oder als Zeiger vom Ursprung aus. Die Polarform beschreibt denselben Punkt durch Betrag und Winkel.": "Liczba zespolona z = a + bi składa się z dwóch liczb rzeczywistych: części rzeczywistej a i części urojonej b. Jednostka urojona i spełnia i² = −{0}. Liczbę z rysuje się jako punkt (a | b) albo jako strzałkę z początku układu. Postać trygonometryczna opisuje ten sam punkt modułem i kątem.",
"Gauss-Ebene mit Betrag und Argument, Addieren und Subtrahieren als Zeiger, Multiplizieren und Dividieren als Drehstreckung, Potenzen (Moivre), Wurzeln und Einheitswurzeln, quadratische Gleichungen mit komplexen Lösungen": "Płaszczyzna zespolona z modułem i argumentem, dodawanie i odejmowanie strzałek, mnożenie i dzielenie jako obrót z rozciągnięciem, potęgi (de Moivre), pierwiastki i pierwiastki z jedynki, równania kwadratowe o rozwiązaniach zespolonych",
"Komplexe Zahlen": "Liczby zespolone",
