"Quadratische Gleichungen": "Równania kwadratowe",
"Wurzeln und Einheitswurzeln": "Pierwiastki i pierwiastki z jedynki",
"Potenzen (Formel von Moivre)": "Potęgi (wzór de Moivre'a)",
"Multiplizieren und Dividieren": "Mnożenie i dzielenie",
"Addieren und Subtrahieren": "Dodawanie i odejmowanie",
"Zahl in der Gauss-Ebene": "Liczba na płaszczyźnie zespolonej",
"Ist die Diskriminante negativ, zieht man die Wurzel mit Hilfe der imaginären Einheit. Jede quadratische Gleichung mit reellen Koeffizienten hat damit zwei Lösungen (oder eine doppelte). Die Sätze von Vieta für Summe und Produkt der Lösungen gelten weiter.": "Jeśli wyróżnik jest ujemny, pierwiastek oblicza się za pomocą jednostki urojonej. Każde równanie kwadratowe o współczynnikach rzeczywistych ma wtedy dwa rozwiązania (albo jedno podwójne). Wzory Viète'a na sumę i iloczyn rozwiązań obowiązują nadal.",
"Aus der Formel von Moivre folgt: Alle n-ten Wurzeln von w haben denselben Betrag, und ihre Winkel unterscheiden sich um den n-ten Teil des Vollwinkels. Für w = {0} heissen sie Einheitswurzeln.": "Ze wzoru de Moivre'a wynika: wszystkie pierwiastki n-tego stopnia z w mają ten sam moduł, a ich kąty różnią się o n-tą część kąta pełnego. Dla w = {0} nazywa się je pierwiastkami z jedynki.",
"Formel von Moivre: Die n-te Potenz hat den n-fachen Winkel, und ihr Betrag ist die n-te Potenz des Betrags. Ist der Betrag grösser als {0}, laufen die Potenzen auf einer Spirale nach aussen, ist er kleiner als {1}, nach innen.": "Wzór de Moivre'a: n-ta potęga ma n razy większy kąt, a jej moduł jest n-tą potęgą modułu. Jeśli moduł jest większy od {0}, potęgi oddalają się po spirali; jeśli jest mniejszy od {1}, zbliżają się do środka.",
"Gerechnet wird wie mit Klammern, mit i² = −{0}. In der Polarform ist das Produkt eine Drehstreckung: Beträge multiplizieren, Winkel addieren. Beim Dividieren ist es umgekehrt: Beträge dividieren, Winkel subtrahieren; in der Normalform erweitert man mit der konjugierten Zahl des Nenners.": "Liczy się jak z nawiasami, pamiętając, że i² = −{0}. W postaci trygonometrycznej iloczyn to obrót z rozciągnięciem: moduły się mnoży, kąty dodaje. Przy dzieleniu jest odwrotnie: moduły się dzieli, kąty odejmuje; w postaci algebraicznej licznik i mianownik mnoży się przez liczbę sprzężoną do mianownika.",
"Komplexe Zahlen addiert und subtrahiert man getrennt nach Realteil und Imaginärteil, genau wie Vektoren in der Ebene. Der Betrag der Differenz ist der Abstand der beiden Punkte.": "Liczby zespolone dodaje się i odejmuje osobno w części rzeczywistej i urojonej, tak jak wektory na płaszczyźnie. Moduł różnicy jest odległością między obydwoma punktami.",
"Bei «Wurzeln» kannst du jede Lösung ziehen: Die Zahl w wird dann als n-te Potenz dieser Lösung neu berechnet.": "W widoku «Pierwiastki» możesz przeciągnąć dowolne rozwiązanie: liczba w zostaje wtedy obliczona na nowo jako n-ta potęga tego rozwiązania.",
"Die Punkte rasten beim Ziehen auf runden Werten ein; genaue Werte tippst du links in die Felder.": "Podczas przeciągania punkty przyciągają się do okrągłych wartości; dokładne wartości wpisujesz w polach po lewej.",
"Die Beträge darf man nicht einfach addieren: {0} (Dreiecksungleichung). Hier: {1}.": "Modułów nie wolno po prostu dodawać: {0} (nierówność trójkąta). Tutaj: {1}.",
"<0>Im Bild:</0> Der Zeiger {1} wird an die Spitze von {2} gehängt. Die Summe ist die Diagonale des Parallelogramms mit den Seiten {3} und {4}.": "<0>Na rysunku:</0> strzałkę {1} doczepia się do grotu {2}. Suma jest przekątną równoległoboku o bokach {3} i {4}.",
"<0>Getrennt rechnen:</0> Realteile und Imaginärteile werden je für sich addiert.": "<0>Liczymy osobno:</0> części rzeczywiste i części urojone dodaje się oddzielnie.",
"<0>Getrennt rechnen:</0> Realteile und Imaginärteile werden je für sich subtrahiert.": "<0>Liczymy osobno:</0> części rzeczywiste i części urojone odejmuje się oddzielnie.",
