"Ziehe {0} und {1}: Die {2} entsteht, indem man den zweiten Zeiger an die Spitze des ersten hängt ({3}). Beim Subtrahieren wird die Gegenzahl −z₂ angehängt.": "Przeciągnij {0} i {1}: {2} powstaje przez doczepienie drugiej strzałki do grotu pierwszej ({3}). Przy odejmowaniu doczepia się liczbę przeciwną −z₂.",
"<0>Abstand:</0> Die Differenz ist der Zeiger von {1} nach {2}; ihr Betrag ist der Abstand der beiden Punkte.": "<0>Odległość:</0> różnica jest strzałką od {1} do {2}; jej moduł to odległość obu punktów.",
"<0>Im Bild:</0> Subtrahieren heisst, die Gegenzahl {1} zu addieren. Der Zeiger {2} wird an die Spitze von {3} gehängt.": "<0>Na rysunku:</0> odejmowanie to dodawanie liczby przeciwnej {1}. Strzałkę {2} doczepia się do grotu {3}.",
"<0>Im Bild:</0> Multiplizieren mit {1} dreht den Zeiger {2} um {3} und streckt ihn mit dem Faktor {4} (Drehstreckung). Das Dreieck {5} ist ähnlich zum Dreieck {6}.": "<0>Na rysunku:</0> mnożenie przez {1} obraca strzałkę {2} o {3} i rozciąga ją w skali {4} (obrót z rozciągnięciem). Trójkąt {5} jest podobny do trójkąta {6}.",
"<0>Polarform:</0> Beträge multiplizieren, Winkel addieren.": "<0>Postać trygonometryczna:</0> moduły się mnoży, kąty dodaje.",
"<0>Polarform:</0> Beträge dividieren, Winkel subtrahieren.": "<0>Postać trygonometryczna:</0> moduły się dzieli, kąty odejmuje.",
"<0>Ausmultiplizieren:</0> Jeder Summand wird mit jedem multipliziert, dann setzt man {1} ein.": "<0>Wymnażanie:</0> każdy składnik mnoży się przez każdy, a potem podstawia {1}.",
