"Produkt": "iloczynie",
"Ziehe {0} und {1}: Beim {2} werden die Beträge multipliziert und die {3}. Die beiden {4} sind ähnlich, denn Multiplizieren mit z₂ dreht um den Winkel von z₂ und streckt mit dessen Betrag. «{5} Drehen und strecken» zeigt die Bewegung.": "Przeciągnij {0} i {1}: w {2} moduły się mnożą, a {3}. Oba {4} są podobne, bo mnożenie przez z₂ obraca o kąt liczby z₂ i rozciąga zgodnie z jej modułem. «{5} Obróć i rozciągnij» pokazuje ten ruch.",
"Winkel ab {0} werden um {1} verkleinert: {2}.": "Kąty od {0} wzwyż zmniejsza się o {1}: {2}.",
"Negative Winkel werden um {0} vergrössert: {1}.": "Kąty ujemne zwiększa się o {0}: {1}.",
"<0>Im Bild:</0> Dividieren durch {1} dreht den Zeiger {2} um {3} zurück und staucht ihn mit dem Faktor {4}. Das Dreieck {5} ist ähnlich zum Dreieck {6}.": "<0>Na rysunku:</0> dzielenie przez {1} obraca strzałkę {2} o {3} wstecz i ściska ją w skali {4}. Trójkąt {5} jest podobny do trójkąta {6}.",
"<0>Mit der konjugierten Zahl erweitern:</0> So wird der Nenner reell, denn {1}.": "<0>Rozszerzamy liczbą sprzężoną:</0> mianownik staje się wtedy rzeczywisty, bo {1}.",
"Durch {0} kann man nicht dividieren. Wähle {1}.": "Przez {0} nie można dzielić. Wybierz {1}.",
"Wegen {0} wachsen die Beträge: Die Potenzen laufen auf einer Spirale nach aussen.": "Ponieważ {0}, moduły rosną: potęgi oddalają się po spirali.",
"Wegen {0} schrumpfen die Beträge: Die Potenzen laufen auf einer Spirale nach innen.": "Ponieważ {0}, moduły maleją: potęgi zbliżają się po spirali do środka.",
"Wegen {0} bleiben alle Potenzen auf dem Einheitskreis.": "Ponieważ {0}, wszystkie potęgi zostają na okręgu jednostkowym.",
"<0>Schritt für Schritt:</0> Jede Multiplikation mit {1} dreht um {2} weiter und streckt mit dem Faktor {3}.": "<0>Krok po kroku:</0> każde mnożenie przez {1} obraca dalej o {2} i rozciąga w skali {3}.",
"<0>Formel von Moivre:</0> Beim Potenzieren wird der Betrag potenziert und der Winkel vervielfacht.": "<0>Wzór de Moivre'a:</0> przy potęgowaniu moduł podnosi się do potęgi, a kąt mnoży.",
