"Ziehe {0} und wähle den Exponenten: Jede {1} dreht um den {2} weiter und streckt mit demselben Faktor. Liegt z auf dem {3}, bleiben alle Potenzen darauf.": "Przeciągnij {0} i wybierz wykładnik: każda {1} obraca dalej o {2} i rozciąga w tej samej skali. Jeśli z leży na {3}, wszystkie potęgi na nim zostają.",
"Die Gleichung {0} hat {1} Lösungen mit dem Betrag {2}": "Równanie {0} ma {1} rozwiązań o module {2}",
"<0>Im Bild:</0> Die Lösungen liegen auf einem Kreis um {1} und teilen ihn in {2} gleiche Teile. Benachbarte Lösungen schliessen den Winkel {3} ein.": "<0>Na rysunku:</0> rozwiązania leżą na okręgu o środku {1} i dzielą go na {2} równych części. Sąsiednie rozwiązania tworzą kąt {3}.",
"<0>Ansatz in Polarform:</0> Aus {1} folgt für die Beträge {2} und für die Winkel {3}.": "<0>Podejście w postaci trygonometrycznej:</0> z {1} wynika dla modułów {2}, a dla kątów {3}.",
