"Stelle {0} und Zuwachs pro Zeitschritt ein: Die {1} sind alle gleich hoch, die {2} liegen auf einer {3}. Ziehe den {4}, um den Bestand zu einem beliebigen Zeitpunkt abzulesen.": "Ustaw: {0} i przyrost na krok czasowy. Wszystkie {1} są jednakowo wysokie, a {2} leżą na {3}. Przeciągnij {4}, aby odczytać wielkość w dowolnej chwili.",
"Stelle {0} und Prozentsatz ein: Jede der {1} ist um denselben Faktor höher als die vorige, die {2} wird immer steiler. Die {3} ist überall gleich lang. Ziehe den {4}.": "Ustaw: {0} i procent. Kolejne {1} rosną za każdym razem o ten sam czynnik, a {2} staje się coraz bardziej stroma. Wszędzie taki sam jest {3}. Przeciągnij {4}.",
"Stelle {0}, {1} und Anteil k ein: Jede der {2} schliesst denselben Anteil der Lücke bis zur Schranke. Die {3} wird immer flacher und kommt der Schranke beliebig nahe. Ziehe den {4}.": "Ustaw: {0}, {1} i udział k. Kolejne {2} zamykają za każdym razem tę samą część luki do granicy. Linia ({3}) staje się coraz bardziej płaska i zbliża się do granicy dowolnie blisko. Przeciągnij {4}.",
"Stelle {0}, {1} und Wachstumskonstante ein: Die {2} wächst zuerst fast exponentiell, am {3} bei halber Schranke am schnellsten und nähert sich dann der Schranke. Ziehe den {4}.": "Ustaw: {0}, {1} i stała wzrostu. Linia ({2}) rośnie najpierw prawie wykładniczo, najszybciej w {3}, przy połowie granicy, a potem zbliża się do granicy. Przeciągnij {4}.",
"Alle Modelle starten beim selben {0}: {1} und {2}. Verstelle die Regler, bis ein Modell die {3} trifft; die {4} zeigt, welches am besten passt.": "Wszystkie modele startują z tej samej wielkości ({0}): {1} i {2}. Przesuwaj suwaki, aż któryś model trafi w {3}; {4} pokazuje, który pasuje najlepiej.",
