"Trage links die {0} und die {1} ein: Jede Zahlung wird mit dem Kalkulationszinssatz zu ihrem {2} abgezinst. Die Summe aller Barwerte ist der {3}; ist er positiv, lohnt sich die Investition.": "Wpisz po lewej dwie rzeczy ({0} oraz {1}): każdą płatność dyskontuje się stopą dyskontową do dziś ({2}). Suma wszystkich wartości bieżących to {3}; jeśli jest dodatnia, inwestycja się opłaca.",
"Ziehe den {0} entlang der {1}: Je höher der Zinssatz, desto kleiner der Kapitalwert. Beim {2} ist der Kapitalwert genau null; liegt er über dem Kalkulationszinssatz, lohnt sich die Investition.": "Przeciągaj punkt ({0}) wzdłuż krzywej ({1}): im wyższa stopa, tym mniejsza wartość bieżąca netto. W jednym miejscu ({2}) wartość bieżąca netto wynosi dokładnie zero; jeśli leży ono powyżej stopy dyskontowej, inwestycja się opłaca.",
"Die {0} summiert die Zahlungen ohne Zins, die {1} die abgezinsten Zahlungen. Wo eine Linie die Nulllinie kreuzt, ist die Investition zurückgeflossen: nach der {2} und nach der {3}.": "Jedna linia ({0}) sumuje płatności bez odsetek, druga ({1}) płatności zdyskontowane. Tam, gdzie linia przecina linię zera, inwestycja się zwróciła: okres zwrotu jest dwojaki ({2} i {3}).",
"Vergleiche {0} und {1}: Ziehe den {2} und lies ab, welche den grösseren Kapitalwert hat. Am {3} sind beide gleich gut; links und rechts davon ist jeweils eine andere besser.": "Porównaj obie możliwości ({0} i {1}): przeciągnij punkt ({2}) i odczytaj, która ma większą wartość bieżącą netto. W jednym miejscu ({3}) obie są równie dobre; po lewej i po prawej lepsza jest za każdym razem inna.",
