"Die {0} erklärt nur einen Teil der Streuung der y-Werte: Der {1} ist das Bestimmtheitsmass r². Unten sind die {2} einzeln aufgetragen. Liegen sie ohne Muster um die {3}, passt eine Gerade; bilden sie einen Bogen, wäre eine Kurve besser.": "Niebieska prosta ({0}) wyjaśnia tylko część zmienności wartości y: miarą jest współczynnik determinacji r² ({1}). Na dole pokazano osobno odchylenia od prostej ({2}). Jeśli układają się bez wzoru wokół poziomej linii ({3}), prosta pasuje; jeśli tworzą łuk, lepsza byłaby krzywa.",
