"Ziehe den {0}: Die {1} gehört zu den Daten ohne Q, die {2} zu allen Punkten. Liegt Q in x-Richtung weit aussen, wirkt er wie ein Hebel. Der {3} zeigt, wie stark sich r und die Steigung ändern.": "Przeciągnij punkt Q ({0}): pierwsza prosta ({1}) należy do danych bez Q, druga ({2}) do wszystkich punktów. Jeśli Q leży daleko w kierunku osi x, działa jak dźwignia. Ramka ({3}) pokazuje, jak mocno zmieniają się r i współczynnik kierunkowy.",
